/**
 * Beautiful and Responsive Cookie Consent
 * https://wordpress.org/plugins/beautiful-and-responsive-cookie-consent/
 * https://beautiful-cookie-banner.com/
 *
 * Cookie name: cookieconsent_status (customizable)
 * Cookie values for simple mode: "allow", "deny", "dismiss"
 * For detailed mode: "savesettings", "allowall", "deny"
 * Category cookies: cookieconsent_status_{suffix} with values "allow" or "deny"
 * Common suffixes: tech, marketing, etc.
 *
 * Events:
 * - beautiful_cookie_consent_initialized: Pushed to dataLayer on page load
 * - beautiful_cookie_consent_updated: Pushed to dataLayer on consent change
 *
 * Note: This plugin has built-in PMW integration via pmw.consent.api.updateSelectively()
 * This module handles reading the cookie on page load for returning visitors.
 *
 * That integration calls the API without a source, on every page load and on
 * every decision, with values it maps from its own categories through arrays in
 * its settings. Unattributed, PMW stored each call as a shop decision, and the
 * stored record then outranked this reader on every later page, so a mapping
 * that sent all categories false kept a visitor denied after they had allowed
 * marketing. relayApiCall() attributes those calls, and
 * supersedeStoredConsent() heals the visitors who already carry such a record.
 */
import {cmpHint, defaultForModel} from "../cmp-defaults.mjs"

const CATEGORIES = ["statistics", "marketing", "preferences"]

/**
 * The file name of the plugin's banner script. It is in the call stack of every
 * call its integration makes, in the V8 ("at c (https://…/cookieNSCconsent.min.js:1:2)")
 * as well as the Firefox and Safari ("c@https://…/cookieNSCconsent.min.js:1:2")
 * format. A page optimizer that concatenates the script into a bundle of its own
 * removes the name, and those calls then stay unattributed.
 *
 * @since 1.69.3
 */
const BCC_SCRIPT_NAME = "cookieNSCconsent"

/**
 * Whether a call stack runs through Beautiful Cookie Consent's banner script.
 *
 * @param {*} stack - an Error().stack string
 * @returns {boolean}
 * @since 1.69.3
 */
export const stackRunsThroughBcc = (stack) => typeof stack === "string" && stack.includes(BCC_SCRIPT_NAME)

/**
 * The current call stack, or null where the browser gives none.
 *
 * @returns {string|null}
 */
const currentStack = () => {
	try {
		const stack = new Error().stack
		return typeof stack === "string" ? stack : null
	} catch (e) {
		return null
	}
}

/**
 * Signals that are specific to Beautiful Cookie Consent, as opposed to the
 * Osano cookieconsent library it is built on, which writes the same
 * cookieconsent_status cookie with allow, deny and dismiss.
 *
 * @returns {boolean}
 */
const bccIsOnThePage = () => {

	if (cmpHint("beautiful_cookie_consent")) return true

	try {
		if (document.querySelector(`script[src*="${BCC_SCRIPT_NAME}"]`)) return true
	} catch (e) {
		// No DOM to query. The cookies below still count.
	}

	// Only its detailed banners write these values and the category cookies.
	if (["savesettings", "allowall", "detailed"].includes(pmw.getCookie("cookieconsent_status"))) return true

	return pmw.getCookieThatContainsRegex(/^cookieconsent_status_[^=]+=(allow|deny)$/) !== false
}

/**
 * Take each category from the cookie reading where it knows the category, and
 * from the fallback where it does not. The reading only knows the category
 * cookie suffixes it expects (statistics, analytics, marketing, preferences,
 * functional, tech), while a shop can name its categories freely.
 *
 * @param {Object} fromCookies
 * @param {Object} fallback
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 */
const preferCookies = (fromCookies, fallback) => {

	const consent = {necessary: true}

	for (const category of CATEGORIES) {
		consent[category] = typeof fromCookies[category] === "boolean"
			? fromCookies[category]
			: fallback?.[category] === true
	}

	return consent
}

export const beautifulCookieConsent = {

	/**
	 * Get the Beautiful Cookie Consent consent from cookies.
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		// Try the default cookie name first
		let consent = pmw.getCookie("cookieconsent_status")

		// If not found, try to detect by looking for cookies that match the pattern
		if (!consent) {
			consent = pmw.getCookieThatContainsRegex(/^cookieconsent_status/)
		}

		if (!consent) return null

		pmw.console.log("Beautiful Cookie Consent CMP consent detected")

		// Simple consent modes: info, opt-in, opt-out
		// Values: "allow", "deny", "dismiss"
		if (consent === "allow" || consent === "dismiss") {
			return {
				statistics : true,
				marketing  : true,
				preferences: true,
				necessary  : true,
			}
		}

		if (consent === "deny") {
			return {
				statistics : false,
				marketing  : false,
				preferences: false,
				necessary  : true,
			}
		}

		// Detailed consent mode (differentiated consent)
		// Values: "savesettings", "allowall", "detailed"
		if (consent === "savesettings" || consent === "detailed" || consent === "allowall") {

			// If "allowall", all categories are allowed
			if (consent === "allowall") {
				return {
					statistics : true,
					marketing  : true,
					preferences: true,
					necessary  : true,
				}
			}

			// For "savesettings" or "detailed", we need to check individual category cookies
			// The plugin uses suffixes like: tech, marketing, etc.
			// Cookie format: cookieconsent_status_{suffix} with values "allow" or "deny"

			return {
				statistics : getCategoryConsent(["statistics", "analytics"]),
				marketing  : getCategoryConsent(["marketing"]),
				preferences: getCategoryConsent(["preferences", "functional", "tech"]),
				necessary  : true,
			}
		}

		// Fallback: try to read category cookies anyway
		// This handles cases where the main cookie has an unexpected value
		const marketingConsent = getCategoryConsent(["marketing"])
		const statisticsConsent = getCategoryConsent(["statistics", "analytics"])
		const preferencesConsent = getCategoryConsent(["preferences", "functional", "tech"])

		// Only return if we found at least one category cookie
		if (marketingConsent !== null || statisticsConsent !== null || preferencesConsent !== null) {
			return {
				statistics : statisticsConsent ?? true,
				marketing  : marketingConsent ?? true,
				preferences: preferencesConsent ?? true,
				necessary  : true,
			}
		}

		return null
	},

	/**
	 * What Beautiful Cookie Consent applies before the visitor has answered.
	 *
	 * The banner type is the consent model, and it only exists on the server:
	 * the banner itself initializes on window load. The server-side hint maps
	 * it the way the plugin maps it for the WP Consent API.
	 *
	 * @returns {{consent: Object, detail: string}|null}
	 * @since 1.69.3
	 */
	getDefault: () => {

		const hint = cmpHint("beautiful_cookie_consent")
		const consent = defaultForModel(hint?.model)

		return consent ? {consent, detail: `${hint.model} banner, from server hint`} : null
	},

	/**
	 * Attribute a consent API call that the plugin's own Pixel Manager
	 * integration made.
	 *
	 * The call is the plugin relaying its state, so PMW applies it without
	 * storing it, like every other CMP relay. Where the plugin's decision cookies
	 * are readable they are the ground truth, and the values the integration
	 * mapped only fill in categories the cookies do not name: a mapping that is
	 * empty or points at the wrong categories sends false for everything. Without
	 * a readable decision cookie the call can be a pre-decision state, because
	 * the integration also runs on the first page view, so it is applied as a
	 * mirror and not recorded as a decision.
	 *
	 * A call whose stack does not run through the plugin's script is not
	 * attributed and keeps being a shop API call.
	 *
	 * @param {{statistics: *, marketing: *, preferences: *, necessary: *}} mapped - the values the call carried
	 * @returns {{consent: Object, decision: boolean, detail: string}|null}
	 * @since 1.69.3
	 */
	relayApiCall: (mapped) => {

		if (!stackRunsThroughBcc(currentStack())) return null

		const fromCookies = beautifulCookieConsent.getConsent()

		if (!fromCookies) {
			return {
				consent : preferCookies({}, mapped),
				decision: false,
				detail  : "integration call without a decision cookie",
			}
		}

		return {
			consent : preferCookies(fromCookies, mapped),
			decision: true,
			detail  : "integration call, read from its decision cookies",
		}
	},

	/**
	 * Whether the plugin's decision outranks a consent record PMW stored.
	 *
	 * On a shop with this plugin, a stored record almost always came from its
	 * integration, which earlier versions stored as a shop decision. Only when
	 * the plugin is on the page and has a decision cookie does its cookie win,
	 * and the record only fills in categories the cookies do not name.
	 *
	 * @param {Object} stored - the stored record
	 * @returns {Object|null} the consent to apply, or null to keep the record
	 * @since 1.69.3
	 */
	supersedeStoredConsent: (stored) => {

		if (!bccIsOnThePage()) return null

		const fromCookies = beautifulCookieConsent.getConsent()

		if (!fromCookies) return null

		return preferCookies(fromCookies, stored)
	},

	/**
	 * Load event listeners for consent changes.
	 *
	 * Note: The Beautiful Cookie Consent plugin already calls pmw.consent.api.updateSelectively()
	 * directly when the Pixel Manager integration is enabled in the plugin settings.
	 * This event listener is a fallback for when that integration is not configured.
	 */
	loadEventListeners: () => {

		// Listen for dataLayer events
		// The plugin pushes "beautiful_cookie_consent_updated" when consent changes
		if (typeof window.dataLayer !== "undefined" && Array.isArray(window.dataLayer)) {
			observeDataLayer()
		} else {
			// Wait for dataLayer to be available
			window.addEventListener("DOMContentLoaded", () => {
				if (typeof window.dataLayer !== "undefined" && Array.isArray(window.dataLayer)) {
					observeDataLayer()
				}
			})
		}
	},
}

/**
 * Get consent for a specific category by checking various possible cookie suffixes.
 *
 * @param {string[]} suffixes - Array of possible suffixes to check
 * @returns {boolean|null} - true if allowed, false if denied, null if not found
 */
const getCategoryConsent = (suffixes) => {
	for (const suffix of suffixes) {
		const value = pmw.getCookie(`cookieconsent_status_${suffix}`)
		if (value === "allow") return true
		if (value === "deny") return false
	}
	return null
}

/**
 * Observe the dataLayer for Beautiful Cookie Consent events.
 */
const observeDataLayer = () => {

	// Create a proxy to intercept pushes to dataLayer
	const originalPush = window.dataLayer.push.bind(window.dataLayer)

	window.dataLayer.push = function (...args) {
		const result = originalPush(...args)

		// Check each pushed item for the consent update event
		args.forEach((item) => {
			if (item && item.event === "beautiful_cookie_consent_updated") {
				handleConsentUpdate(item)
			}
		})

		return result
	}
}

/**
 * Handle consent update from dataLayer event.
 *
 * @param {Object} eventData - The dataLayer event object
 */
const handleConsentUpdate = (eventData) => {

	pmw.console.log("Beautiful Cookie Consent consent update detected via dataLayer")

	// The event contains:
	// - cookieconsent_status: "allow", "deny", "savesettings", "allowall", etc.
	// - cookieconsent_status_{suffix}: "allow" or "deny" for each category

	const mainStatus = eventData.cookieconsent_status

	// Simple modes
	if (mainStatus === "allow" || mainStatus === "dismiss") {
		pmw.consent.api.updateSelectively({
			statistics : true,
			marketing  : true,
			preferences: true,
			necessary  : true,
			source     : "cmp",
		})
		return
	}

	if (mainStatus === "deny") {
		pmw.consent.api.updateSelectively({
			statistics : false,
			marketing  : false,
			preferences: false,
			necessary  : true,
			source     : "cmp",
		})
		return
	}

	if (mainStatus === "allowall") {
		pmw.consent.api.updateSelectively({
			statistics : true,
			marketing  : true,
			preferences: true,
			necessary  : true,
			source     : "cmp",
		})
		return
	}

	// Detailed mode - read category values from event data
	if (mainStatus === "savesettings" || mainStatus === "detailed") {
		const data = {
			statistics : getConsentFromEventData(eventData, ["statistics", "analytics"]),
			marketing  : getConsentFromEventData(eventData, ["marketing"]),
			preferences: getConsentFromEventData(eventData, ["preferences", "functional", "tech"]),
			necessary  : true,
		}

		pmw.consent.api.updateSelectively({...data, source: "cmp"})
	}
}

/**
 * Get consent value from event data for a category.
 *
 * @param {Object} eventData - The dataLayer event object
 * @param {string[]} suffixes - Array of possible suffixes to check
 * @returns {boolean} - true if allowed, false otherwise
 */
const getConsentFromEventData = (eventData, suffixes) => {
	for (const suffix of suffixes) {
		const key = `cookieconsent_status_${suffix}`
		if (eventData[key] === "allow") return true
		if (eventData[key] === "deny") return false
	}
	// Default to false if no category found
	return false
}
