/**
 * CookieYes, GDPR Cookie Consent (Cookie Law Info)
 * https://wordpress.org/plugins/cookie-law-info/
 */

import {applyDefault, fromAcceptedSlugs, loaderScriptPresent} from "../cmp-defaults.mjs"

const SOURCE = "CookieYes"

/**
 * CookieYes category slug -> PMW category. The same mapping the cookie reader
 * uses.
 */
const SLUGS = {
	statistics : ["analytics"],
	marketing  : ["advertisement"],
	preferences: ["functional"],
}

export const cookieyes = {

	/**
	 * Get the CookieYes cookies
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		/**
		 * Process the new cookieyes-consent cookie that contains all the information
		 */

		    // on first load CookieYes sets the categories with no values (facepalm)
		    // let consent = "consentid:cWZkOGRjNzFzb1R3a0I4VlJMYXM1ZEJjVEs5aU4zcTQ,consent:,action:,necessary:,functional:,analytics:,performance:,advertisement:,other:"
			// let consent = "consentid:cnpZSGg2SDZzWXJodEc3TWF3UTdKVVM3UmtKWHc3SEk,consent:yes,action:yes,necessary:yes,functional:yes,analytics:no,performance:yes,advertisement:yes"
		let consent = pmw.getCookie("cookieyes-consent")

		if (consent) {

			// This cookie has the following structure:
			// consentid:cnpZSGg2SDZzWXJodEc3TWF3UTdKVVM3UmtKWHc3SEk,consent:yes,action:yes,necessary:yes,functional:yes,analytics:no,performance:yes,advertisement:yes
			// First split the comma-separated values into an array
			// Then split each array item into a key value pair. The key and the value are separated by a colon.
			// Then create an object from the key value pairs.
			const values = consentToJson(consent)

			/**
			 * CookieYes writes the cookieyes-consent cookie on the very first page
			 * view, before the visitor has answered the banner. What it holds then
			 * varies by the law it thinks applies, so only the action says whether
			 * a decision exists. See hasAnsweredBanner().
			 *
			 * Reading anything else as a decision marks the visitor as having
			 * chosen, which makes PMW skip the region check, so a visitor outside
			 * the configured explicit consent regions stayed blocked instead of
			 * being unlocked. Sibling of the Cookie Script guard in
			 * cookie-script.mjs and the Complianz guard in complianz.mjs.
			 *
			 * The new cookie is authoritative about whether a decision exists, so we
			 * do not fall through to the legacy cookielawinfo-* cookies here.
			 */
			if (!hasAnsweredBanner(values)) {
				pmw.console.log("CookieYes cookie detected, but the visitor hasn't answered the banner yet. Ignoring it.")
				return null
			}

			pmw.console.log("CookieYes CMP consent detected")

			// The visitor has decided. For the three tracking categories every value
			// that is not an explicit "yes" is a denial, which keeps the "" to false
			// mapping for a category CookieYes left empty in a decided cookie.
			// Necessary follows the other CMP readers instead: it is allowed unless
			// it has been denied explicitly.
			return {
				statistics : values.analytics === "yes",
				marketing  : values.advertisement === "yes",
				preferences: values.functional === "yes",
				necessary  : values.necessary !== "no",
			}
		}

		/**
		 * Check if at least one of the cookies is set
		 *
		 * @param cookieNames
		 * @returns {boolean}
		 */
		const isOneCookieSet = (cookieNames) => {
			for (let key in cookieNames) {
				for (let cookieName of cookieNames[key]) {
					if (pmw.getCookie(cookieName)) {
						return true
					}
				}
			}
			return false
		}

		/**
		 * Process the old cookieyes-* cookies
		 *
		 * @param cookieNames
		 * @returns {boolean}
		 */
		const getCookieValue = (cookieNames) => {

			for (let cookieName of cookieNames) {
				let value = pmw.getCookie(cookieName)
				if (value === "yes") {
					return true
				} else if (value === "no") {
					return false
				}
			}

			return true
		}

		const cookieNames = {
			statistics : [
				"cookielawinfo-checkbox-analytics",
				"cookielawinfo-checkbox-analytiques",
				"cookieyes-analytics",
			],
			marketing  : [
				"cookielawinfo-checkbox-advertisement",
				"cookielawinfo-checkbox-performance",
				"cookielawinfo-checkbox-publicite",
				"cookieyes-advertisement",
			],
			preferences: [
				"cookielawinfo-checkbox-functional",
				"cookielawinfo-checkbox-preferences",
				"cookieyes-functional",
			],
			necessary  : [
				"cookielawinfo-checkbox-necessary",
				"cookielawinfo-checkbox-necessaire",
				"cookieyes-necessary",
			],
		}

		// If at least one of the cookies is set to "yes" or "no", then return the CookieYes consent
		if (isOneCookieSet(cookieNames)) {

			pmw.console.log("CookieYes CMP consent detected")

			return  {
				statistics : getCookieValue(cookieNames.statistics),
				marketing  : getCookieValue(cookieNames.marketing),
				preferences: getCookieValue(cookieNames.preferences),
				necessary  : getCookieValue(cookieNames.necessary),
			}
		}

		return null
	},

	/**
	 * What CookieYes applies before the visitor has answered.
	 *
	 * The pre-decision cookieyes-consent cookie holds it once CookieYes has
	 * written its defaults, which happens at DOMContentLoaded on the first page
	 * view and is then there on every later page until the visitor answers.
	 * Before that, the configuration CookieYes prints in the head says the
	 * same: the law it applies, and each category's default under that law.
	 *
	 * @returns {{consent: Object, detail: string}|null}
	 * @since 1.69.3
	 */
	getDefault: () => {

		const cookie = pmw.getCookie("cookieyes-consent")

		if (cookie) {

			const values = consentToJson(cookie)

			if (hasAnsweredBanner(values)) return null

			if (["analytics", "advertisement", "functional"].some(slug => values[slug])) {
				return {
					consent: {
						statistics : values.analytics === "yes",
						marketing  : values.advertisement === "yes",
						preferences: values.functional === "yes",
						necessary  : true,
					},
					detail : "pre-decision cookie",
				}
			}
		}

		return defaultFromWebApp() || defaultFromConfiguration(window._ckyConfig)
	},

	/**
	 * Web app (cloud) mode, for the asynchronous CMP wait in cmp-wait.mjs.
	 *
	 * The web app's script.js is the loader, printed with the id "cookieyes"
	 * and served from cdn-cookieyes.com/client_data/. getCkyConsent() comes
	 * with banner.js, which script.js loads asynchronously, so on a first page
	 * view it is usually not there when PMW decides.
	 *
	 * @since 1.69.3
	 */
	asyncLoader: {

		isPresent: () => loaderScriptPresent([
			"script#cookieyes",
			"script[src*=\"cdn-cookieyes.com/client_data/\"]",
		]),

		poll: () => {

			if (typeof window.getCkyConsent !== "function") return null

			const state = window.getCkyConsent()

			if (!state || typeof state !== "object") return null

			// An answer given on this page is relayed by the
			// cookieyes_consent_update listener. This covers an answer that is
			// already in the store when the banner script comes up.
			if (state.isUserActionCompleted === true) {

				const categories = state.categories || {}

				return {
					decision: {
						statistics : categories.analytics === true,
						marketing  : categories.advertisement === true,
						preferences: categories.functional === true,
						necessary  : categories.necessary !== false,
					},
					detail  : "answered banner, from getCkyConsent()",
				}
			}

			// Only a law CookieYes names settles the model. Anything else keeps
			// PMW waiting, and at the cap, denying, until CookieYes' own
			// pre-decision update says what it applies.
			return defaultFromWebApp()
		},
	},

	loadEventListeners: () => {

		document.addEventListener("cookieyes_consent_update", (e) => {

			/**
			 * CookieYes fires this event for its own pre-decision defaults too, not
			 * only for an answered banner: both default writers end in a
			 * cookieyes_consent_update dispatch on the first page view. The event
			 * detail carries the categories but nothing that tells the two apart,
			 * so we ask the store the same question the cookie reader asks.
			 *
			 * Without this, the "no law applies here" default relayed a grant for
			 * every category before the visitor had answered anything.
			 *
			 * CookieYes writes the cookie before it dispatches, so the action is
			 * already in place by the time we read it here.
			 */
			if (!hasAnsweredBanner(consentToJson(pmw.getCookie("cookieyes-consent") || ""))) {

				// Not a decision, but CookieYes' own default for this visitor,
				// which is what implicit consent mode applies until one arrives.
				if (applyDefault(SOURCE, fromAcceptedSlugs(e?.detail?.accepted, SLUGS), "pre-decision update")) return

				pmw.console.log("CookieYes consent update received, but the visitor hasn't answered the banner yet. Ignoring it.")
				return
			}

			let data = {
				statistics : e.detail.accepted.includes("analytics"),
				marketing  : e.detail.accepted.includes("advertisement"),
				preferences: e.detail.accepted.includes("functional"),
				necessary  : e.detail.accepted.includes("necessary"),
			}

			pmw.consent.api.updateSelectively({...data, source: "cmp"})
		}, true)
	},
}

/**
 * Whether the cookieyes-consent cookie carries an answered banner.
 *
 * "action:yes" is the one and only answer signal. CookieYes defines its own
 * public isUserActionCompleted as `"yes" === _ckyGetFromStore("action")`, and
 * it shows the banner on `!_ckyGetFromStore("action")`, so nothing else in the
 * cookie states whether a visitor decided.
 *
 * The "consent" key in particular does not, and reading it as one is how a
 * banner nobody had answered was read as consent. Before the visitor answers,
 * CookieYes writes a default set through one of two functions, and neither of
 * them writes an action:
 *
 *   - the regional default writes `consent:no` (`consent:yes` under CCPA with
 *     Global Privacy Control) and leaves action absent,
 *   - the "no law applies here" default writes `action:no` with `consent:yes`
 *     and grants every category.
 *
 * So every pre-decision state carries an explicit consent value, and accepting
 * it marked the visitor as having chosen. That skips the region check in
 * countryUnlock(), which leaves a visitor outside the configured explicit
 * consent regions blocked for good. Ticket 3448373394, geistlich.us: a US
 * shop on CookieYes where the Meta pixel never loaded, so no browser purchase
 * event and no _fbp cookie was ever written.
 *
 * @param values {Object} - the raw key value pairs of the cookie
 * @returns {boolean}
 */
const hasAnsweredBanner = (values) => values.action === "yes"

/**
 * The defaults CookieYes applies, derived from its configuration the way its
 * own _ckySetInitialState() derives them.
 *
 * Under GDPR a category is off unless it is necessary or defaults to on, and
 * CookieYes keeps every later category off once one is off. Under CCPA every
 * category runs until the visitor opts out. With no law, everything runs.
 *
 * @param config {Object|undefined} - window._ckyConfig
 * @returns {{consent: Object, detail: string}|null}
 * @since 1.69.3
 */
/**
 * The pre-decision default in web app (cloud) mode.
 *
 * Connected to a CookieYes account, the plugin loads CookieYes' own script
 * from its CDN instead of printing _ckyConfig, and the pre-decision cookie is
 * only written later, at DOMContentLoaded. So neither source exists when PMW
 * decides, and an opt-in visitor was tracked before answering. getCkyConsent()
 * states the law: "gdpr" means nothing optional before an answer, "ccpa" means
 * opt-out, so tracking runs until the visitor objects.
 *
 * getCkyConsent() is defined by banner.js, which the web app's script.js
 * loads asynchronously, so on a first page view it is usually not there yet
 * when PMW decides. The asynchronous CMP wait (asyncLoader above) holds PMW's
 * decision until it is. Verified on a web app install, 2026-09-24.
 *
 * @returns {{consent: Object, detail: string}|null}
 * @since 1.69.3
 */
const defaultFromWebApp = () => {

	if (typeof window.getCkyConsent !== "function") return null

	let state

	try {
		state = window.getCkyConsent()
	} catch (e) {
		return null
	}

	if (!state || state.isUserActionCompleted) return null

	if (state.activeLaw === "gdpr") {
		return {
			consent: {statistics: false, marketing: false, preferences: false, necessary: true},
			detail : "law gdpr, from getCkyConsent()",
		}
	}

	if (state.activeLaw === "ccpa") {
		return {
			consent: {statistics: true, marketing: true, preferences: true, necessary: true},
			detail : "law ccpa, from getCkyConsent()",
		}
	}

	return null
}

const defaultFromConfiguration = (config) => {

	const categories = config?._categories
	const law = config?._bannerConfig?.settings?.applicableLaw

	if (!Array.isArray(categories) || typeof law !== "string") return null

	const accepted = []
	let value = "yes"

	for (const category of categories) {

		if (law === "gdpr" && !category.isNecessary && !category.defaultConsent?.gdpr) value = "no"

		if (value === "yes") accepted.push(category.slug)
	}

	return {consent: fromAcceptedSlugs(accepted, SLUGS), detail: `law ${law || "none"}, from configuration`}
}

/**
 * Turn the comma separated cookie into its raw key value pairs.
 *
 * The values stay strings on purpose. On the first page view CookieYes writes
 * every category as an empty string, and an empty string must stay
 * distinguishable from an explicit "no".
 *
 * @param consent {string}
 * @returns {Object}
 */
const consentToJson = (consent) => {

	let consentObj = {}

	consent.split(",").forEach((item) => {
		let [key, value] = item.split(":")
		consentObj[key]  = value
	})

	return consentObj
}
