/**
 * FAZ Cookie Manager
 * https://wordpress.org/plugins/faz-cookie-manager/
 *
 * Cookie name: fazcookie-consent
 * Cookie format (URL-encoded): "key:value,key:value,..."
 *   - Reserved keys: consentid, action, rev
 *   - Category keys (canonical): necessary, functional, analytics, performance, marketing
 *   - Legacy alias: advertisement (treated as marketing, matches FAZ's own tcf-cmp.min.js)
 *   - Service keys: svc.<id>
 *   - Value "yes" means granted, anything else means denied
 *
 * Revision check: if the configured _fazConfig._consentRevision is > 1 and the
 * cookie's "rev" is below it, the consent is considered stale and treated as missing
 * (the visitor must re-consent).
 *
 * Event: fazcookie_consent_update is dispatched on document whenever the
 * visitor changes consent. detail = { accepted: [slugs], rejected: [slugs], action }.
 */

import {applyDefault, fromAcceptedSlugs} from "../cmp-defaults.mjs"

const SOURCE = "FAZ Cookie Manager"

/**
 * FAZ category slug -> PMW category, the same mapping as the cookie reader.
 */
const SLUGS = {
	statistics : ["analytics", "performance"],
	marketing  : ["marketing", "advertisement"],
	preferences: ["functional"],
}

/**
 * The actions FAZ uses for a state that is not a visitor decision: its
 * jurisdiction defaults on a first visit, and a Global Privacy Control signal
 * it applied on its own.
 */
const PRE_DECISION_ACTIONS = ["init", "gpc"]

export const fazCookieManager = {

	/**
	 * Read the FAZ Cookie Manager consent cookie and map it to PMW categories.
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		const parsed = parseFazConsentCookie()

		if (!parsed) return null

		pmw.console.log("FAZ Cookie Manager CMP consent detected")

		return mapFazCategoriesToPmw(parsed)
	},

	/**
	 * What FAZ applies before the visitor has answered.
	 *
	 * FAZ writes no cookie before a decision. It records the state it seeded in
	 * window._fazConsentReady, and before it has seeded anything, its
	 * configuration in the head says the same: the law that applies to this
	 * visitor and each category's default under it.
	 *
	 * @returns {{consent: Object, detail: string}|null}
	 * @since 1.69.3
	 */
	getDefault: () => {

		if (parseFazConsentCookie()) return null

		const ready = window._fazConsentReady

		if (ready && PRE_DECISION_ACTIONS.includes(ready.action) && Array.isArray(ready.accepted)) {
			return {consent: fromAcceptedSlugs(ready.accepted, SLUGS), detail: `pre-decision state (${ready.action})`}
		}

		return defaultFromConfiguration()
	},

	/**
	 * Listen for FAZ consent updates and forward them to PMW.
	 */
	loadEventListeners: () => {
		document.addEventListener("fazcookie_consent_update", fazConsentUpdate)
		document.addEventListener("fazcookie_consent_ready", fazConsentReady)
	},
}

/**
 * FAZ announces its initial state once per page load. On a first visit that
 * is its default for this visitor, which implicit consent mode applies until a
 * decision arrives. A stored choice ("restore") was already read from the
 * cookie at boot.
 *
 * @param {CustomEvent} e
 * @since 1.69.3
 */
const fazConsentReady = (e) => {

	const detail = e && e.detail ? e.detail : null

	if (!detail || !PRE_DECISION_ACTIONS.includes(detail.action)) return

	applyDefault(SOURCE, fromAcceptedSlugs(detail.accepted, SLUGS), `pre-decision state (${detail.action})`)
}

/**
 * The defaults FAZ derives from its configuration, the way its own
 * _fazSeedInitialState() does: under GDPR, and for categories a runtime geo
 * ruleset names, a category is off unless it is necessary or defaults to on.
 * Under CCPA and with no law every category runs.
 *
 * @returns {{consent: Object, detail: string}|null}
 * @since 1.69.3
 */
const defaultFromConfiguration = () => {

	const config = window._fazConfig
	const categories = config?._categories

	if (!Array.isArray(categories) || typeof window.getFazConsent !== "function") return null

	const state = window.getFazConsent()

	if (state?.isUserActionCompleted) return null

	const law = typeof state?.activeLaw === "string" ? state.activeLaw : ""
	const runtimeGeo = !!config._runtimeGeo

	const accepted = categories
		.filter(category => {

			if (category.isNecessary) return true

			if ((runtimeGeo && category.defaultFromRuleset) || law === "gdpr") return !!category.defaultConsent?.gdpr

			return true
		})
		.map(category => category.slug)

	return {consent: fromAcceptedSlugs(accepted, SLUGS), detail: `law ${law || "none"}, from configuration`}
}

/**
 * Forward a FAZ consent update to PMW.
 *
 * @param {CustomEvent} e
 */
const fazConsentUpdate = (e) => {

	const detail = e && e.detail ? e.detail : null

	// The initial sync the banner fires on page load is no decision. It carries
	// FAZ' own default for this visitor, which implicit consent mode applies.
	// PMW already read a stored decision via getConsent() at boot.
	if (detail && PRE_DECISION_ACTIONS.includes(detail.action)) {
		applyDefault(SOURCE, fromAcceptedSlugs(detail.accepted, SLUGS), `pre-decision state (${detail.action})`)
		return
	}

	// Re-read the cookie so we use the canonical, persisted state rather than
	// trying to interpret the event payload (which uses category slugs only).
	const parsed = parseFazConsentCookie()

	if (!parsed) return

	pmw.consent.api.updateSelectively({...mapFazCategoriesToPmw(parsed), source: "cmp"})
}

/**
 * Parse the fazcookie-consent cookie into a flat object.
 *
 * @returns {Object|null}
 */
const parseFazConsentCookie = () => {

	const raw = pmw.getCookie("fazcookie-consent")

	if (!raw) return null

	let decoded = raw

	try {
		decoded = decodeURIComponent(raw)
	} catch (err) {
		// Cookie was stored without encoding; use the raw value.
	}

	const out = {}

	decoded.split(",").forEach((pair) => {
		const idx = pair.indexOf(":")
		if (idx === -1) return
		const key   = pair.substring(0, idx).trim()
		const value = pair.substring(idx + 1).trim()
		if (key) out[key] = value
	})

	// Revision invalidation: if the site requires a newer revision than the
	// one recorded in the cookie, treat the cookie as absent.
	const configuredRevision = (typeof window !== "undefined" && window._fazConfig && parseInt(window._fazConfig._consentRevision, 10)) || 0
	const cookieRevision     = parseInt(out.rev, 10) || 0

	if (configuredRevision > 1 && cookieRevision < configuredRevision) return null

	return out
}

/**
 * Map FAZ category values to PMW's four buckets.
 *
 * @param {Object} parsed
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 */
const mapFazCategoriesToPmw = (parsed) => {

	const isYes = (key) => parsed[key] === "yes"

	return {
		statistics : isYes("analytics") || isYes("performance"),
		marketing  : isYes("marketing") || isYes("advertisement"),
		preferences: isYes("functional"),
		necessary  : true,
	}
}
