/**
 * Consent Management
 **/

/**
 * Load modules
 */
import cmps from "./cmps.mjs"
import {optInDefault, optOutDefault} from "./cmp-defaults.mjs"
import {CMP_WAIT_MAX_MS, findAsyncCmps, namesOf, pollCandidates, pollLate, waitForAsyncCmp} from "./cmp-wait.mjs"

/**
 * Tracks each consent decision step for the diagnostic summary log.
 * Populated during load(), logged in loadTrigger().
 *
 * @type {string[]}
 * @private
 */
let _consentDecisionLog = []

/**
 * Tracks the source of the consent decision for use in suppressed pixel logs.
 *
 * @type {{type: string, detail: string}|null}
 * @private
 */
let _decisionSource = null

/**
 * Whether a visitor decision has been applied, at boot from a CMP or through
 * the consent API later on the page. Once one is in, a CMP default must never
 * overwrite it.
 *
 * @type {boolean}
 * @private
 */
let _decisionRecorded = false

/**
 * Whether load() has finished. A CMP default that arrives after that has to
 * tell the pixels about the change itself, one that arrives during load()
 * does not.
 *
 * @type {boolean}
 * @private
 */
let _loaded = false

/**
 * Counts every decision and every applied CMP default, so the asynchronous
 * CMP wait can tell that one came in through the CMP's own events while it
 * was waiting. See waitForAsyncCmps().
 *
 * @type {number}
 * @private
 */
let _signals = 0

/**
 * Called on every signal, to end the wait at once instead of at its next poll.
 *
 * @type {Set<function(): void>}
 * @private
 */
const _signalListeners = new Set()

/**
 * Note a decision or an applied CMP default.
 *
 * @returns {void}
 * @private
 */
const signal = () => {

	_signals++

	for (const listener of [..._signalListeners]) {
		try {
			listener()
		} catch (e) {
			// A listener must not break the path that raised the signal.
		}
	}
}

/**
 * Initialize and set default values
 */
export let settings = {
	categories      : {
		statistics : true,
		marketing  : true,
		preferences: true,
		necessary  : true, // Necessary cookies are always allowed
	},
	visitorHasChosen: false,

	get: (data = null) => {

		if (data === null) {
			return settings
		}

		let result = {}

		for (let key of data) {
			result[key] = settings[key]
		}

		return result
	},

	set: (data) => {
		for (let key in data) {
			settings[key] = data[key]
		}
	},
}

/**
 * Load the consent management
 *
 * @returns {Promise<void>}
 * @public
 */
export const load = async () => {

	/** Load the event listeners for each CMP */
	loadCmpEventListeners()

	/** Set the default values */
	// console.log("setDefaultValues")
	setExplicitConsentModeDefaults()

	/**
	 * Get the consent values from the cookies
	 * */

	await loadConsentFromCmps()

	/** Unlocks countries in allowed regions */
	await countryUnlock()

	/** Update the pixel consent for pixel type CMPs */
	// pmw.scriptTagObserver.observe(document.head, {childList: true, subtree: true})
	// jQuery(document).on("DOMContentLoaded", () => pmw.scriptTagObserver.disconnect())

	/** Trigger the consent management loaded event */
	loadTrigger()
}

const loadConsentFromCmps = async () => {
	let cmpResult = getConsentFromCmps()

	if (cmpResult) {
		pmw.consent.categories.set(cmpResult.consent)
		pmw.consent.settings.set({visitorHasChosen: true})
		_decisionRecorded = true

		_consentDecisionLog.push(`cmp: ${cmpResult.source}`)
		_decisionSource = {type: "cmp", detail: cmpResult.source}
		pmw.console.log(`CMP consent applied from: ${cmpResult.source}`, cmpResult.consent)
		return
	}

	_consentDecisionLog.push("cmp: none")

	/**
	 * No visitor decision. In explicit consent mode the defaults already deny
	 * everything and the region check decides what to unlock, so a CMP default
	 * has nothing to add there.
	 *
	 * In implicit mode PMW used to grant everything at this point, and that is
	 * what fired the pixels before the visitor had answered an opt-in banner:
	 * PMW keeps its own scripts out of several CMPs' blocking, so the CMP never
	 * caught them. Where the CMP states what it applies before a decision, PMW
	 * now applies the same. Where nothing states it, today's behaviour stays.
	 *
	 * @since 1.69.3
	 */
	if (explicitConsentModeActive()) {
		pmw.console.log("No CMP consent detected. Consent categories remain at defaults.")
		return
	}

	const cmpDefault = getDefaultFromCmps()

	if (cmpDefault) {
		applyCmpDefault(cmpDefault)
		return
	}

	if (await waitForAsyncCmps()) return

	_consentDecisionLog.push("cmp default: none")
	pmw.console.log("No CMP consent and no CMP default detected. Consent categories remain at defaults.")
}

/**
 * Apply what a CMP applies before the visitor has answered its banner.
 *
 * A CMP default is not a decision. It never marks the visitor as having chosen,
 * so every consumer of visitorHasChosen, the region check among them, keeps
 * treating the visitor as undecided. It is applied only in implicit consent
 * mode, and only as long as no decision has been applied. Once the CMP reports
 * a decision, the regular update path takes over and a later default is
 * ignored.
 *
 * A default can arrive after load(), for example once an asynchronously loaded
 * CMP script knows the visitor's region. It then replaces the earlier default,
 * and PMW tells the pixels: newly granted categories get their pixels loaded,
 * and pmw:consent:update carries the change to Google Consent Mode and the
 * server-side consent snapshot.
 *
 * @param {Object} cmpDefault
 * @param {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}} cmpDefault.consent
 * @param {string} cmpDefault.source - the CMP's name
 * @param {string} [cmpDefault.detail] - what the default was derived from
 * @returns {boolean} whether the default was applied
 * @public
 * @since 1.69.3
 */
export const applyCmpDefault = ({consent, source = "Unknown CMP", detail = ""} = {}) => {

	if (typeof consent !== "object" || consent === null) return false

	const label = detail ? `${source} (${detail})` : source

	if (explicitConsentModeActive()) {
		pmw.console.log(`CMP default from ${label} ignored: explicit consent mode decides the defaults itself.`)
		return false
	}

	if (_decisionRecorded || settings.visitorHasChosen) {
		pmw.console.log(`CMP default from ${label} ignored: a visitor decision is already applied.`)
		return false
	}

	const next = {
		statistics : consent.statistics === true,
		marketing  : consent.marketing === true,
		preferences: consent.preferences === true,
		necessary  : true,
	}

	const previous = {...settings.categories}

	categories.set(next)

	_decisionSource = {type: "cmp_default", detail: label}

	signal()

	if (!_loaded) {
		_consentDecisionLog.push(`cmp default: ${label}`)
		pmw.console.log(`CMP default applied from: ${label}`, next)
		return true
	}

	pmw.console.log(`CMP default applied after load from: ${label}`, next)

	const changed = Object.keys(next).some(key => previous[key] !== next[key])

	if (!changed) return true

	if (Object.keys(next).some(key => next[key] && !previous[key])) {
		window.pmw?.bus?.emitAndDispatch("pmw:load-pixels")
	}

	document.dispatchEvent(new CustomEvent("pmw:consent:update", {detail: {...next, source: "cmp_default"}}))

	return true
}

/**
 * Note that a visitor decision has been applied. The consent API calls this for
 * every state it saves, whether a CMP relayed it or a shop snippet set it.
 *
 * @returns {void}
 * @public
 * @since 1.69.3
 */
export const recordDecision = () => {
	_decisionRecorded = true
	signal()
}

/**
 * Whether a visitor decision has been applied on this page.
 *
 * @returns {boolean}
 * @public
 * @since 1.69.3
 */
export const decisionRecorded = () => _decisionRecorded

/**
 * The consent model PMW's server side resolved for a CMP, if any.
 *
 * Only models that do not depend on the visitor's location are printed, so the
 * hint is safe in a cached page. See Environment::get_cmp_consent_hints().
 *
 * @param {string} key - the CMP key, for example "complianz"
 * @returns {Object|null}
 * @public
 * @since 1.69.3
 */
export const getCmpHint = (key) => {

	const hint = pmwDataLayer?.general?.consent_management?.cmp_hints?.[key]

	return typeof hint === "object" && hint !== null ? hint : null
}

/**
 * Hold the consent decision for a CMP that loads asynchronously.
 *
 * Runs in implicit consent mode only, after the CMP readers found no decision
 * and no CMP could state its default synchronously. It applies only when the
 * loader script of CookieYes (web app), Cookiebot, OneTrust / CookiePro or
 * Usercentrics is in the DOM; see their asyncLoader and cmp-wait.mjs.
 *
 * load() awaits this, and main() awaits load() before it registers the event
 * listeners and imports the pixels, so the wait holds the whole start-up.
 * Entry events dispatched meanwhile are held by the bus until main() flushes
 * them after the pixels have loaded (see pmw.bus.flushEntryEvents()), and the
 * CMP listeners are registered at the top of load(), so an answer given
 * during the wait ends it at once.
 *
 * - The CMP reports in time: its pre-decision state is applied as a CMP
 *   default (opt-in denies the optional categories, opt-out grants them).
 * - A decision or a CMP default arrives through the CMP's events: that is it.
 * - Nothing within CMP_WAIT_MAX_MS: the optional categories are denied as a
 *   fail-safe CMP default, and PMW keeps asking for a while. When the CMP
 *   reports later, through its events or the follow-up, the regular late
 *   default path in applyCmpDefault() grants what it allows and loads the
 *   pixels.
 *
 * Visitors excluded from tracking at init are not held: they load no pixel.
 *
 * @returns {Promise<boolean>} whether an asynchronous CMP was found and handled
 * @private
 * @since 1.69.3
 */
const waitForAsyncCmps = async () => {

	const candidates = findAsyncCmps(cmps)

	if (candidates.length === 0) return false

	const name = namesOf(candidates)

	if (visitorExcludedAtInit()) {
		pmw.console.log(`${name} is loading, but this visitor is excluded from tracking, so PMW does not wait for it.`)
		return false
	}

	const contexts     = new Map()
	const startSignals = _signals
	const settled      = () => _decisionRecorded || _signals > startSignals

	// Already able to answer: nothing to wait for.
	const immediate = pollCandidates(candidates, contexts)

	if (immediate) {
		_consentDecisionLog.push(`cmp wait: ${immediate.cmp.name} ready at once`)
		applyAsyncCmpAnswer(immediate, false)
		return true
	}

	pmw.console.log(`Waiting for ${name} to report its consent model (up to ${CMP_WAIT_MAX_MS / 1000} s)`)

	const outcome = await waitForAsyncCmp({
		candidates,
		contexts,
		settled,
		subscribe: (listener) => {
			_signalListeners.add(listener)
			return () => _signalListeners.delete(listener)
		},
	})

	if (outcome.status === "ready") {
		pmw.console.log(`${outcome.cmp.name} ready after ${outcome.elapsed} ms`)
		_consentDecisionLog.push(`cmp wait: ${outcome.cmp.name} ready after ${outcome.elapsed} ms`)
		applyAsyncCmpAnswer(outcome, false)
		return true
	}

	if (outcome.status === "settled") {
		const what = _decisionRecorded ? "a visitor decision" : "its default"
		pmw.console.log(`${name} ready after ${outcome.elapsed} ms: it reported ${what}`)
		_consentDecisionLog.push(`cmp wait: ${name} reported ${what} after ${outcome.elapsed} ms`)
		return true
	}

	pmw.console.log(`${name} timed out after ${outcome.elapsed} ms, treating as denied until it reports`)
	_consentDecisionLog.push(`cmp wait: ${name} timed out after ${outcome.elapsed} ms`)

	applyCmpDefault({
		consent: optInDefault(),
		source : name,
		detail : `no answer within ${CMP_WAIT_MAX_MS} ms, denied until it reports`,
	})

	const timeoutSignals = _signals

	pollLate({
		candidates,
		contexts,
		settled : () => _decisionRecorded || _signals > timeoutSignals,
		onAnswer: (answer) => {
			pmw.console.log(`${answer.cmp.name} reported after the wait had timed out`)
			applyAsyncCmpAnswer(answer, true)
		},
	})

	return true
}

/**
 * Apply what an asynchronously loaded CMP answered. See cmp-wait.mjs for the
 * answer shapes.
 *
 * @param {{cmp: Object, result: Object}} answer
 * @param {boolean} afterTimeout - whether the fail-safe denial is in place
 * @returns {void}
 * @private
 * @since 1.69.3
 */
const applyAsyncCmpAnswer = ({cmp, result}, afterTimeout) => {

	const source = cmp.name || "Unknown CMP"
	const detail = result.detail || ""

	if (result.decision) {
		_decisionSource = {type: "cmp", detail: source}
		pmw.console.log(`${source} holds a visitor decision (${detail}). Relaying it.`)
		pmw.consent?.api?.updateSelectively?.({...result.decision, source: "cmp"})
		return
	}

	if (result.consent) {
		applyCmpDefault({consent: result.consent, source, detail})
		return
	}

	// The CMP applies no restriction PMW can read, for example because no
	// consent is required for this visitor. Implicit consent mode's own
	// defaults apply. After a timeout the fail-safe denial has to be lifted.
	if (afterTimeout) {
		applyCmpDefault({consent: optOutDefault(), source, detail: `${detail}, implicit consent mode defaults apply`})
		return
	}

	_consentDecisionLog.push(`cmp default: none (${source}: ${detail})`)
	pmw.console.log(`${source}: ${detail}. Implicit consent mode defaults apply.`)
}

/**
 * Whether the visitor is known to be excluded from tracking at init, without
 * touching the flags main() sets from pmw.isVisitorAllowedSync() later.
 *
 * @returns {boolean}
 * @private
 * @since 1.69.3
 */
const visitorExcludedAtInit = () => {

	try {
		if (pmw.isBotUserAgent?.() === true || pmw.isAutomatedBrowser?.() === true) return true

		const cached = pmw.retrieveData?.("visitorAllowed")

		if (cached !== null && cached !== undefined && !JSON.parse(cached)) return true
	} catch (e) {
		// Unknown means not excluded, the same as main() treats it.
	}

	return false
}

/**
 * Ask every CMP integration for its pre-decision state, and take the first one.
 *
 * @returns {{consent: Object, source: string, detail: string}|null}
 * @private
 */
const getDefaultFromCmps = () => {

	for (let cmp of cmps) {

		if (typeof cmp.getDefault !== "function") continue

		let result

		try {
			result = cmp.getDefault()
		} catch (e) {
			pmw.console.error(`The ${cmp.name || "CMP"} consent default reader failed. Skipping it.`, e)
			continue
		}

		if (!result || typeof result.consent !== "object" || result.consent === null) continue

		return {consent: result.consent, source: cmp.name || "Unknown CMP", detail: result.detail || ""}
	}

	return null
}

/**
 * Load the event listeners for each CMP
 *
 * @returns {void}
 * @private
 */
const loadCmpEventListeners = () => {
	for (let cmp of cmps) {

		if (typeof cmp.loadEventListeners !== "function") {
			continue
		}
		cmp.loadEventListeners()
	}
}

/**
 * Set the default values
 *
 * @returns {void}
 * @private
 */
const setExplicitConsentModeDefaults = () => {

	/**
	 * Setup defaults
	 *
	 * TODO: Extend with country specific settings.
	 *
	 * If explicit consent mode is active,
	 * and no consent has been given yet,
	 * and there are regions set in the settings,
	 * then set the consent values accordingly.
	 * (if a country is set then only set the consent to false if the visitor is from that country)
	 * Otherwise set the consent values to false.
	 */

	let isExplicit = pmw.consent.explicitConsentModeActive()
	let defaultConsent = !isExplicit

	let defaults = {
		statistics : defaultConsent,
		marketing  : defaultConsent,
		preferences: defaultConsent,
		necessary  : true,
	}

	if (isExplicit) {
		_consentDecisionLog.push("mode: explicit")
		pmw.console.log("Consent mode: explicit. Initial defaults:", defaults)
	} else {
		_consentDecisionLog.push("mode: implicit")
		pmw.console.log("Consent mode: implicit. Initial defaults:", defaults)
	}

	pmw.consent.categories.set(defaults)
}

/**
 * Check if PMW is in explicit consent mode
 *
 * @returns {boolean}
 * @private
 */
export const explicitConsentModeActive = () => pmwDataLayer?.general?.consent_management?.explicit_consent

/**
 * Returns the consent values
 *
 * @returns any
 * @public
 * */
pmw.getConsentValues = () => pmw.consent.settings.get()

/**
 * Set the consent values
 *
 * @param {Object} consentValues
 * @param {boolean} consentValues.statistics
 * @param {boolean} consentValues.marketing
 * @param {boolean} consentValues.preferences
 * @param {boolean} consentValues.necessary
 *
 * @returns {void}
 * @public
 */
// export const setCategories = ({statistics, marketing, preferences, necessary}) => {
export const categories = {

	set: ({
			  // The fallbacks must read from settings.categories.
			  // pmw.consent.settings.get() returns the settings root, which has no
			  // category keys, so reading them from there would silently overwrite
			  // any category not passed in with undefined.
			  statistics = settings.categories.statistics,
			  marketing = settings.categories.marketing,
			  preferences = settings.categories.preferences,
			  necessary = settings.categories.necessary,
		  }) => {
		settings.categories.statistics  = statistics
		settings.categories.marketing   = marketing
		settings.categories.preferences = preferences
		settings.categories.necessary   = necessary
	},

	get: (data = null) => {

		if (data === null) {
			return settings.categories
		}

		let result = {}

		for (let key of data) {
			result[key] = settings.categories[key]
		}

		return result
	},
}

/**
 * Get the consent values from various cookies
 *
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean} | null}
 * - statistics: Boolean - Indicates if consent has been given for statistics cookies
 * - marketing: Boolean - Indicates if consent has been given for marketing cookies
 * - preferences: Boolean - Indicates if consent has been given for preference cookies
 * - necessary: Boolean - Indicates if consent has been given for necessary cookies
 * @private
 */
const getConsentFromCmps = () => {

	/**
	 * PMW Cookie Consent
	 *
	 * The PMW only saves the pmw_cookie_consent when consent is set through our
	 * API by something that owns the decision itself, which means a CMP that has
	 * no state PMW can read back. States relayed by our own CMP integrations are
	 * deliberately not stored (see forgetConsentState() in api.mjs): the CMP owns
	 * those and PMW reads them back through getConsent() on the next page load.
	 * Storing them would let a record that has no expiry, and that a cookie purge
	 * does not reach, outrank the CMP and keep granting after the CMP itself has
	 * no decision left.
	 *
	 * So a stored record wins over the CMP cookies, which is what makes a CMP that
	 * decides to start using our API work.
	 *
	 * TODO: Maybe store in PMW's data store. However, we can't set a duration there. Store in the data store if no duration is needed.
	 */

	const storageKey = "pmw_cookie_consent"

	let consent = pmw.retrieveData(storageKey, true) || pmw.getCookie(storageKey)

	if (consent) {

		// Depending of if the value comes from window.localStorage or a cookie,
		// it might be a string or an object
		consent = typeof consent === "object" ? consent : JSON.parse(consent)

		consent = consentBackwardsCompatibilityUpdate(consent)

		const superseding = getConsentSupersedingStoredRecord(consent)

		if (superseding) {
			forgetStoredRecord(storageKey)
			pmw.console.log(`${superseding.source} decision cookie supersedes the stored PMW consent record. The record has been removed.`, {stored: consent, applied: superseding.consent})
			return superseding
		}

		return {consent, source: "PMW cookie/storage"}
	}

	/**
	 * Get the consent values from the CMPs
	 */
	for (let cmp of cmps) {

		if (typeof cmp.getConsent !== "function") {
			continue
		}

		/**
		 * One reader that throws must not take the others down with it. An
		 * uncaught error here aborted the whole consent load, and the loader
		 * then fell back to denying everything on every page. The Usercentrics
		 * reader did exactly that on shops without Google Consent Mode.
		 *
		 * @since 1.69.3
		 */
		let consent

		try {
			consent = cmp.getConsent()
		} catch (e) {
			pmw.console.error(`The ${cmp.name || "CMP"} consent reader failed. Skipping it.`, e)
			continue
		}

		if (!consent) {
			continue
		}

		return {consent, source: cmp.name || "Unknown CMP"}
	}

	return null
}

/**
 * Ask the CMP integrations whether their own decision outranks the stored record.
 *
 * A CMP whose built-in PMW integration called the consent API without a source
 * got its relay stored as a shop decision by earlier versions, and that record
 * then outranked the CMP on every later page. An integration that can tell its
 * own record apart heals those visitors here. See supersedeStoredConsent() in
 * cmps/beautiful-cookie-consent.mjs.
 *
 * @param {Object} stored - the stored record
 * @returns {{consent: Object, source: string}|null}
 * @private
 * @since 1.69.3
 */
const getConsentSupersedingStoredRecord = (stored) => {

	for (let cmp of cmps) {

		if (typeof cmp.supersedeStoredConsent !== "function") continue

		let consent

		try {
			consent = cmp.supersedeStoredConsent(stored)
		} catch (e) {
			pmw.console.error(`The ${cmp.name || "CMP"} stored record check failed. Skipping it.`, e)
			continue
		}

		if (typeof consent !== "object" || consent === null) continue

		return {consent, source: cmp.name || "Unknown CMP"}
	}

	return null
}

/**
 * Drop the stored consent record, from window.localStorage and the cookie.
 *
 * @param {string} storageKey
 * @returns {void}
 * @private
 * @since 1.69.3
 */
const forgetStoredRecord = (storageKey) => {

	if (pmw.retrieveData(storageKey, true) !== undefined) pmw.deleteDataKey(storageKey, true)

	if (pmw.getCookie(storageKey)) pmw.deleteCookie(storageKey)
}

/**
 * Attribute a consent API call that did not name its source.
 *
 * Some CMPs ship their own PMW integration and call pmw.consent.api without a
 * source, which made PMW store their relay as a shop decision. An integration
 * that recognizes such a call returns the state to apply instead, and the API
 * then treats it as relayed from the CMP: applied, not stored. A call no
 * integration recognizes stays a shop API call.
 *
 * @param {{statistics: *, marketing: *, preferences: *, necessary: *}} data - the values the call carried
 * @returns {{consent: Object, decision: boolean, source: string, detail: string}|null}
 * @public
 * @since 1.69.3
 */
export const attributeApiCall = (data) => {

	for (let cmp of cmps) {

		if (typeof cmp.relayApiCall !== "function") continue

		let relay

		try {
			relay = cmp.relayApiCall(data)
		} catch (e) {
			pmw.console.error(`The ${cmp.name || "CMP"} API call attribution failed. Skipping it.`, e)
			continue
		}

		if (!relay || typeof relay.consent !== "object" || relay.consent === null) continue

		return {
			consent : relay.consent,
			decision: relay.decision !== false,
			source  : cmp.name || "Unknown CMP",
			detail  : relay.detail || "",
		}
	}

	return null
}

/**
 * This is to ensure backwards compatibility for consent that was set before the change
 * If key consent.analytics exists, rewrite it to consent.statistics
 *
 * @param consent
 * @return {Object}
 */
const consentBackwardsCompatibilityUpdate = (consent) => {

	if (!consent.hasOwnProperty("analytics") && !consent.hasOwnProperty("ads")) return consent

	if (consent.hasOwnProperty("analytics")) {
		consent.statistics = consent.analytics
		delete consent.analytics
	}

	if (consent.hasOwnProperty("ads")) {
		consent.marketing = consent.ads
		delete consent.ads
	}

	consent.preferences = true
	consent.necessary   = true

	return consent
}

/**
 * TODO: Extend with country specific settings.
 *
 * Unlock countries in allowed regions
 *
 * If explicit consent mode is active,
 * and no consent has been given yet,
 * and there are regions set in the settings,
 * then set the consent values accordingly.
 * If a country is set then only set the consent to false
 * if the visitor is from that country.
 * Otherwise set the consent values to true.
 *
 * @returns {Promise<void>}
 * @private
 *
 * TODO: Verify all the conditions and calls
 */
const countryUnlock = async () => {

	// Return if explicit consent mode is not active
	if (!explicitConsentModeActive()) {
		_consentDecisionLog.push("region check: skipped (not explicit mode)")
		return
	}

	// Return if the visitor has already chosen
	if (pmw.consent.settings.get().visitorHasChosen) {
		_consentDecisionLog.push("region check: skipped (visitor already chose via CMP)")
		pmw.console.log("Region check skipped: visitor already chose consent via CMP")
		return
	}

	// Return if there are no regions set in the settings
	if (!pmwDataLayer?.general?.consent_management?.restricted_regions) {
		_consentDecisionLog.push("region check: skipped (no restricted regions configured)")
		pmw.console.log("Region check skipped: no restricted regions configured. Consent defaults remain (all blocked in explicit mode).")
		return
	}

	const restrictedRegions = pmwDataLayer.general.consent_management.restricted_regions
	const browserGeo = await pmw.getBrowserGeo()

	// If the country is in the list of restricted countries, then set the consent values to false
	// else set the consent values to true
	if (browserIsInRestrictedRegion(browserGeo)) {

		_consentDecisionLog.push(`region: ${browserGeo?.countryCode || "unknown"} restricted → blocked`)
		_decisionSource = {type: "region_restricted", detail: browserGeo?.countryCode || "unknown"}
		pmw.console.log("Region check: restricted → blocking all categories", {visitor: browserGeo, restrictedRegions, match: true})
		pmw.consent.categories.set({statistics: false, marketing: false, preferences: false, necessary: true})
		return
	}

	_consentDecisionLog.push(`region: ${browserGeo?.countryCode || "unknown"} not restricted → unlocked`)
	_decisionSource = {type: "region_unlocked", detail: browserGeo?.countryCode || "unknown"}
	pmw.console.log("Region check: not restricted → unlocking all categories", {visitor: browserGeo, restrictedRegions, match: false})
	pmw.consent.categories.set({statistics: true, marketing: true, preferences: true, necessary: true})
}

const browserIsInRestrictedRegion = (browserGeo) => {

	if (browserGeo === null) {
		return true
	}

	if (browserGeo.countryCode && pmwDataLayer?.general?.consent_management?.restricted_regions.includes(browserGeo.countryCode)) {
		return true
	}

	if (browserGeo.regionCode && pmwDataLayer?.general?.consent_management?.restricted_regions.includes(browserGeo.regionCode)) {
		return true
	}

	return false
}

/**
 * Whether a pixel may fire, given the consent categories.
 *
 * The pixel name is only carried for the suppression log. Consent itself has
 * been category based since direct support for the two pixel based CMPs was
 * dropped.
 */
export const canPixelBeFired = (category, pixelName) => {

	if (pmw.consent.categories.get()[category]) {
		pmw.console.log(`The category ${category} has been approved. Loading the ${pixelName} pixel.`)
		return true
	}

	logSuppressedPixel(category, pixelName)
	return false
}

export const logSuppressedPixel = (category, pixelName) => {

	let mode = explicitConsentModeActive() ? "explicit" : "implicit"
	let sourceInfo = ""

	if (_decisionSource) {
		sourceInfo = `, source: ${_decisionSource.type} (${_decisionSource.detail})`
	}

	console.log(`Pixel Manager: The pixel has not loaded because you have not given consent for it yet. - mode: ${mode}, category: ${category}, pixel: ${pixelName}${sourceInfo}`)
}

/**
 * Trigger the consent management loaded event
 *
 * @returns {void}
 * @private
 */
const loadTrigger = () => {

	_loaded = true

	// Trigger an event once the PMW consent management has been loaded
	document.dispatchEvent(new Event("pmw_cookie_consent_management_loaded"))
	document.dispatchEvent(new Event("pmwCookieConsentManagementLoaded"))

	const categories = pmw.consent.categories.get()
	pmw.console.log(`Consent decision: ${_consentDecisionLog.join(" | ")}`, categories)
	pmw.console.log("Loaded consent category settings: ", categories)
}

/**
 * Reload the page when the user clicks a cosent button
 *
 * @param ids
 * @param classes
 * @returns {void}
 * @public
 */
export const cmpConsentClickObserver = ({ids = [], classes = []}) => {

	// if buttonClasses don't have a dot in front of them, add it
	classes = classes.map(buttonClass => buttonClass.startsWith(".") ? buttonClass : "." + buttonClass)

	const observer = new MutationObserver((mutationsList, observer) => {
		// Look through all mutations that just occured
		for (let mutation of mutationsList) {
			// If the addedNodes property has one or more nodes
			if (mutation.addedNodes.length) {

				if (classes.length > 0) {

					const elements = document.querySelectorAll(classes.join(", "))

					elements.forEach(element => {
						element.addEventListener("click", () => {
							location.reload()
						})
						observer.disconnect()
					})
				}

				if (ids.length > 0) {

					ids.forEach(buttonId => {
						const button = document.getElementById(buttonId)
						if (button) {
							button.addEventListener("click", () => {
								location.reload()
							})
							// Once we have added the click event listener, there's no need to observe anymore
							observer.disconnect()
						}
					})
				}
			}
		}
	})

	observer.observe(document.body, {childList: true, subtree: true})
}
