/**
 * Cookiefirst CMP
 * https://cookiefirst.com
 * https://cookiefirst.com/wordpress-cookie-consent-plugin/
 * https://support.cookiefirst.com/hc/de/articles/360011568738-Javascript-API
 */
export const cookiefirst = {

	/**
	 * Get the Cookiefirst cookie.
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		// let consent = "{"necessary":true,"performance":true,"functional":true,"advertising":true,"timestamp":1731043717,"type":"category","version":"73d03af8-0302-48f4-8d17-802e03d4959b"}"
		const cookie = pmw.getCookie("cookiefirst-consent")

		if (!cookie) return null

		const consent = parseConsentCookie(cookie)

		if (!consent) {
			pmw.console.log("Cookiefirst cookie could not be parsed. Ignoring it.")
			return null
		}

		pmw.console.log("Cookiefirst CMP consent detected", consent)

		return mapCookiefirstConsent(consent)
	},

	/**
	 * Cookiefirst
	 *
	 * Cookiefirst dispatches cf_consent on window whenever the visitor saves a
	 * choice, with the consent object as the detail.
	 *
	 * The listener used to read an undeclared variable and threw on every
	 * event, so no in-page decision ever reached PMW: a visitor who declined
	 * stayed tracked on that page, and one who accepted stayed blocked.
	 *
	 * @since 1.69.3
	 */
	loadEventListeners: () => {

		window.addEventListener("cf_consent", (event) => {

			const consent = event?.detail

			// A withdrawn consent arrives without a consent object. Nothing
			// that is not stated as granted is granted.
			const data = typeof consent === "object" && consent !== null
				? mapCookiefirstConsent(consent)
				: mapCookiefirstConsent({})

			pmw.consent.api.updateSelectively({...data, source: "cmp"})
		}, true)
	},
}

/**
 * Map Cookiefirst's categories onto PMW's.
 *
 * A category Cookiefirst does not name is denied. It used to be granted, which
 * is what the deny by default policy forbids: an unknown must never unblock a
 * pixel. Same change as the Cookiebot and OneTrust readers.
 *
 * @param consent {Object}
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 * @since 1.69.3
 */
const mapCookiefirstConsent = (consent) => ({
	statistics : consent.performance === true,
	marketing  : consent.advertising === true,
	preferences: consent.functional === true,
	necessary  : consent.necessary !== false,
})

/**
 * Parse the cookiefirst-consent cookie, which Cookiefirst writes either as
 * JSON or as a URI encoded object literal.
 *
 * The readers run one after another, so a cookie that does not parse must not
 * throw here.
 *
 * @param cookie {string}
 * @returns {Object|null}
 */
const parseConsentCookie = (cookie) => {

	try {

		let parsed

		if (isValidJson(cookie)) {
			parsed = JSON.parse(cookie)
		} else {
			let consent = decodeURI(cookie)
			consent     = consent.replace(/'/g, "\"") // Replace single quotes with double quotes as JSON requires double quotes
			consent     = decodeURIComponent(consent)
			consent     = consent.replace(/(\w+):/g, "\"$1\":") // Add double quotes to keys
			parsed      = JSON.parse(consent)
		}

		if (typeof parsed !== "object" || parsed === null) return null

		return parsed

	} catch (e) {
		return null
	}
}

const isValidJson = (str) => {
	try {
		JSON.parse(str)
	} catch (e) {
		return false
	}
	return true
}
