/**
 * Cookie Compliance (free version)
 * https://wordpress.org/plugins/cookie-notice/
 */
export const cookieCompliance = {

	/**
	 * Get the Cookie Compliance cookie.
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		// Free version
		let consent = pmw.getCookie("cookie_notice_accepted")

		// If the cookie is set, it contains the string "true" or "false"
		if (consent) {

			pmw.console.log("Cookie Compliance CMP (by hu-manity.co) consent detected")

			// Convert the string "true" to true and "false" to false
			consent = consent === "true"

			return {
				statistics : consent,
				marketing  : consent,
				preferences: consent,
				necessary  : true,
			}
		}

		// Paid version
		consent = pmw.getCookie("hu-consent")

		if (consent) {

			pmw.console.log("Cookie Compliance CMP (by hu-manity.co) consent detected")

			try {
				consent = JSON.parse(consent)
			} catch (e) {
				pmw.console.log("Cookie Compliance cookie could not be parsed. Ignoring it.")
				return null
			}

			if (typeof consent?.categories !== "object" || consent.categories === null) {
				pmw.console.log("Cookie Compliance cookie detected, but it carries no consent categories. Ignoring it.")
				return null
			}

			return mapHuCategories(consent.categories)
		}

		return null
	},

	/**
	 * Cookie Compliance by hu-manity.co (free and pro)
	 * If visitor accepts cookies in Cookie Notice by hu-manity.co unblock the scripts (free version)
	 * https://wordpress.org/support/topic/events-on-consent-change/#post-15202792
	 */
	loadEventListeners: () => {
		document.addEventListener("set-consent.hu", (e) => {

			// Validate that e.detail.categories exists
			if (!e?.detail?.categories) return

			pmw.consent.api.updateSelectively({...mapHuCategories(e.detail.categories), source: "cmp"})
		}, true)
	},
}

/**
 * Map the hu-manity.co category levels onto PMW's categories.
 *
 * 1 = necessary, 2 = preferences, 3 = statistics, 4 = marketing
 *
 * A level the cookie or the event does not name is denied. The cookie reader
 * granted it, and the event relay passed undefined, which kept whatever PMW
 * held before, a grant for everything in implicit consent mode.
 *
 * @param categories {Object}
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 * @since 1.69.3
 */
const mapHuCategories = (categories) => ({
	statistics : categories["3"] === true,
	marketing  : categories["4"] === true,
	preferences: categories["2"] === true,
	necessary  : categories["1"] !== false,
})
