/**
 * Usercentrics
 *
 * https://usercentrics.com/
 * https://docs.usercentrics.com/#/cmp-v2-ui-api
 * https://docs.usercentrics.com/#/cmp-v2-ui-api?id=getservicesbaseinfo
 *
 * Although Usercentrics adopts some of the Google consent categories,
 * they don't process and save the "preferences" category.
 */
import {applyDefault, loaderScriptPresent, optInDefault} from "../cmp-defaults.mjs"

const SOURCE = "Usercentrics"

export const usercentrics = {

	/**
	 * Get the Usercentrics cookie.
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		const consent = readGcmState()

		/**
		 * ucData exists without a gcm key when Google Consent Mode is off in
		 * the Usercentrics settings. Reading .analyticsStorage off it threw,
		 * which aborted the loop over every CMP reader and put PMW into its
		 * deny-all fallback on every page, for every visitor.
		 *
		 * @since 1.69.3
		 */
		if (!consent) return null

		pmw.console.log("Usercentrics CMP consent detected")

		return {
			statistics : consent.analyticsStorage !== "denied",
			marketing  : consent.adStorage !== "denied",
			preferences: true,
			necessary  : true,
		}
	},

	/**
	 * What Usercentrics applies before the visitor has answered.
	 *
	 * The v2 UI says whether this visitor has to be asked for consent before
	 * anything non-essential runs: UC_UI.isConsentRequired(). It only exists
	 * once the asynchronously loaded Usercentrics script has initialized; see
	 * the UC_UI_INITIALIZED listener. The v3 API answers asynchronously and is
	 * handled there only.
	 *
	 * @returns {{consent: Object, detail: string}|null}
	 * @since 1.69.3
	 */
	getDefault: () => {

		const ui = window.UC_UI

		if (typeof ui?.isConsentRequired !== "function") return null

		return ui.isConsentRequired() === true
			? {consent: optInDefault(), detail: "consent required and not given yet"}
			: null
	},

	/**
	 * For the asynchronous CMP wait in cmp-wait.mjs.
	 *
	 * Both the v2 loader (app.usercentrics.eu) and the v3 loader
	 * (web.cmp.usercentrics.eu) are printed with the id "usercentrics-cmp"
	 * and load the CMP asynchronously.
	 *
	 * @since 1.69.3
	 */
	asyncLoader: {

		isPresent: () => loaderScriptPresent([
			"script#usercentrics-cmp",
			"script[src*=\"app.usercentrics.eu\"]",
			"script[src*=\"web.cmp.usercentrics.eu\"]",
		]),

		poll: (context = {}) => {

			const ui = window.UC_UI

			if (typeof ui?.isConsentRequired === "function") {

				if (typeof ui.isInitialized === "function" && ui.isInitialized() !== true) return null

				return ui.isConsentRequired() === true
					? {consent: optInDefault(), detail: "consent required and not given yet"}
					: {consent: null, detail: "no consent required, or an answer given earlier"}
			}

			return pollV3(context)
		},
	},

	/**
	 * Usercentrics Event Listeners
	 *
	 * https://docs.usercentrics.com/#/v2-events?id=usage-as-window-event
	 */
	loadEventListeners: () => {

		// ucCategory: {functional: true, marketing: true, essential: true, customcategory03: true}
		// statistics seem to be customcategory03 on their website.
		// document.addEventListener("ucEvent", e => {
		// 	if (e.detail && e.detail.event == "consent_status") {
		// 		// check for consent status of service "Google Ads Remarketing"
		// 		if (e.detail["Google Ads Remarketing"] === true) {
		// 			pmw.console.log("Google Ads Remarketing has consent")
		// 		} else {
		// 			pmw.console.log("Google Ads Remarketing has no consent")
		// 		}
		// 	}
		// }, true)

		/**
		 * Usercentrics loads asynchronously, so its answer to "does this
		 * visitor have to be asked first" usually arrives after PMW read the
		 * consent.
		 *
		 * @since 1.69.3
		 */
		window.addEventListener("UC_UI_INITIALIZED", () => {

			const cmpDefault = usercentrics.getDefault()

			if (cmpDefault) {
				applyDefault(SOURCE, cmpDefault.consent, cmpDefault.detail)
				return
			}

			applyV3Default()
		}, true)

		// The v3 API may already be there when PMW boots. It answers
		// asynchronously, so its default arrives after load either way.
		if (!window.UC_UI) applyV3Default()

		// https://docs.usercentrics.com/#/v2-events?id=uc_ui_cmp_event
		document.addEventListener("UC_UI_CMP_EVENT", event => {

			const type = event?.detail?.type

			if (type === "ACCEPT_ALL") pmw.consent.api.acceptAll({source: "cmp"})

			if (type === "DENY_ALL") pmw.consent.api.revokeAll({source: "cmp"})

			/**
			 * The handler read ucData off an undeclared variable and threw, so a
			 * visitor who saved a custom selection was never relayed.
			 *
			 * @since 1.69.3
			 */
			if (type === "SAVE") {

				const consent = readGcmState()

				if (consent) {
					pmw.consent.api.updateSelectively({
						statistics : consent.analyticsStorage === "granted",
						marketing  : consent.adStorage === "granted",
						preferences: true,
						necessary  : true,
						source     : "cmp",
					})
				}
			}
		}, true)
	},
}

/**
 * The v3 API: getConsentDetails() resolves with the consent state, whose
 * "required" says whether this visitor has to be asked, and whose "type" stays
 * "IMPLICIT" until the visitor has made an explicit choice.
 *
 * @returns {void}
 * @since 1.69.3
 */
const applyV3Default = () => {

	const cmp = window.__ucCmp

	if (typeof cmp?.getConsentDetails !== "function") return

	Promise.resolve()
		.then(() => cmp.getConsentDetails())
		.then(details => {

			const consent = details?.consent

			if (consent?.required === true && consent?.type !== "EXPLICIT") {
				applyDefault(SOURCE, optInDefault(), "consent required and not given yet (v3)")
			}
		})
		.catch(() => {
			// No answer is no default.
		})
}

/**
 * The v3 API for the asynchronous CMP wait. getConsentDetails() answers
 * asynchronously, so the first poll asks, and a later poll returns the answer.
 *
 * @param {Object} context - one per wait, see cmp-wait.mjs
 * @returns {{consent: Object|null, detail: string}|null}
 * @since 1.69.3
 */
const pollV3 = (context) => {

	const cmp = window.__ucCmp

	if (typeof cmp?.getConsentDetails !== "function") return null

	if (context.v3 === undefined) {

		context.v3 = null

		Promise.resolve()
			.then(() => cmp.getConsentDetails())
			.then(details => {

				const consent = details?.consent

				if (typeof consent !== "object" || consent === null) {
					// Not an answer yet. Ask again on the next poll.
					context.v3 = undefined
					return
				}

				context.v3 = consent.required === true && consent.type !== "EXPLICIT"
					? {consent: optInDefault(), detail: "consent required and not given yet (v3)"}
					: {consent: null, detail: "no consent required, or an answer given earlier (v3)"}
			})
			.catch(() => {
				context.v3 = undefined
			})
	}

	return context.v3 ?? null
}

/**
 * Read the Google Consent Mode state Usercentrics keeps in localStorage.
 *
 * @returns {Object|null} - null when there is no ucData, when it does not
 *                          parse, or when it carries no gcm state
 */
const readGcmState = () => {

	try {
		const ucData = window.localStorage.getItem("ucData")

		if (!ucData) return null

		const gcm = JSON.parse(ucData)?.gcm

		return typeof gcm === "object" && gcm !== null ? gcm : null

	} catch (e) {
		return null
	}
}
