/**
 * GDPR Cookie Compliance Plugin by Moove Agency
 * https://wordpress.org/plugins/gdpr-cookie-compliance/
 *
 * TODO write documentation on how to set up the plugin in order for this to work properly
 */

import {cmpHint, optInDefault} from "../cmp-defaults.mjs"

export const mooveCookieCompliance = {

	/**
	 * Get the GDPR Cookie Compliance Plugin by Moove Agency cookie.
	 *
	 * example cookie: %7B%22strict%22%3A%221%22%2C%22thirdparty%22%3A%220%22%2C%22advanced%22%3A%221%22%7D
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		let consent = pmw.getCookie("moove_gdpr_popup")

		if (consent) {

			try {
				consent = JSON.parse(consent)
			} catch (e) {
				pmw.console.log("GDPR Cookie Compliance cookie could not be parsed. Ignoring it.")
				return null
			}

			if (typeof consent !== "object" || consent === null) return null

			pmw.console.log("GDPR Cookie Compliance CMP (by Moove Agency) consent detected")

			return {
				statistics: consent.thirdparty !== "0",
				marketing : consent.advanced !== "0",
				preferences: true,
				necessary: consent.strict !== "0"
			}
		}

		return null
	},

	/**
	 * What Moove applies before the visitor has answered: its banner is opt-in,
	 * and the "enable on first visit" switch of each group decides whether it
	 * runs anyway. Third party cookies map to statistics and advanced cookies to
	 * marketing, as in the cookie reader.
	 *
	 * Moove localizes its settings in the footer, so on a first page view they
	 * are usually not there yet when PMW reads the consent, and the server-side
	 * hint carries the same switches. With the geo location addon the banner
	 * only shows in some regions, and neither applies.
	 *
	 * @returns {{consent: Object, detail: string}|null}
	 * @since 1.69.3
	 */
	getDefault: () => {

		const settings = window.moove_frontend_gdpr_scripts

		if (settings?.enabled_default) {

			if (settings.geo_location === "true" || settings.geo_location === true) return null

			return {
				consent: optInDefault({
					statistics: Number(settings.enabled_default.third_party) === 1,
					marketing : Number(settings.enabled_default.advanced) === 1,
				}),
				detail : "first visit defaults",
			}
		}

		const hint = cmpHint("moove")

		if (hint?.model === "optin") {
			return {consent: optInDefault(hint.defaults || {}), detail: "first visit defaults, from server hint"}
		}

		return null
	},

	loadEventListeners: () => {

		/**
		 * Moove localizes its settings in the footer, after PMW registered its
		 * listeners on most pages, so the click observer was never set up and a
		 * decision only reached PMW on the next page. Wait for the document
		 * when the settings are not there yet.
		 *
		 * @since 1.69.3
		 */
		if (!window.moove_frontend_gdpr_scripts) {

			if (document.readyState === "loading") {
				document.addEventListener("DOMContentLoaded", observeMooveButtons)
			}

			return
		}

		observeMooveButtons()
	},
}

const MOOVE_BUTTON_CLASSES = ["moove-gdpr-infobar-allow-all", "moove-gdpr-modal-allow-all", "moove-gdpr-modal-save-settings"]

/**
 * Reload the page after a decision, so the cookie Moove wrote is read at boot.
 *
 * Moove prints its banner markup with the page, so the buttons can already be
 * in the document; the mutation observer only reaches buttons added later.
 *
 * @returns {void}
 */
const observeMooveButtons = () => {

	if (!window.moove_frontend_gdpr_scripts) return

	document.querySelectorAll(MOOVE_BUTTON_CLASSES.map(name => "." + name).join(", ")).forEach(button => {
		button.addEventListener("click", () => location.reload())
	})

	pmw.consent.cmpConsentClickObserver({classes: MOOVE_BUTTON_CLASSES})
}
