/**
 * A bounded wait for CMPs that load asynchronously.
 *
 * In implicit consent mode PMW decides in the head. CookieYes in web app mode,
 * Cookiebot, OneTrust / CookiePro and Usercentrics all load the part of their
 * script that knows the visitor's consent model asynchronously, so on a first
 * page view that part is often not there yet when PMW decides. With no decision
 * and no readable default, PMW used to fall back to granting everything, and
 * the pixels fired before an opt-in banner had been answered.
 *
 * When one of these CMPs is actually on the page (its loader script is in the
 * DOM) and nothing about the visitor's state can be read synchronously, PMW
 * now holds its consent decision, and with it the pixel loading, until the CMP
 * reports, for at most CMP_WAIT_MAX_MS. See consent.mjs for when the wait
 * applies and what happens at its end.
 *
 * An adapter takes part by offering `asyncLoader`:
 *
 *   isPresent(): boolean
 *     Whether the CMP's own loader script is in the DOM. Only the loader
 *     counts, never a plugin flag: a plugin that is installed but prints no
 *     loader would otherwise cost every visitor the full wait.
 *
 *   poll(context): null | {consent: Object|null, detail: string} | {decision: Object, detail: string}
 *     null while the CMP cannot state the visitor's consent model yet.
 *     {consent} once it can: the categories it applies before the visitor has
 *     answered, or consent: null when it applies no restriction PMW can read
 *     (no consent required for this visitor), in which case implicit consent
 *     mode's own defaults stay.
 *     {decision} when the CMP holds an answered banner, which is relayed as a
 *     decision.
 *     `context` is a plain object that lives as long as one wait and its late
 *     follow-up, for adapters whose API answers asynchronously.
 *
 * @since 1.69.3
 */

/**
 * How long PMW holds its consent decision for an asynchronously loading CMP.
 *
 * Long enough for a CMP served from its CDN on a normal connection, short
 * enough that a CMP that never loads (blocked, broken, removed) costs a first
 * page view at most this much before PMW goes on with the fail-safe denial.
 *
 * @type {number}
 */
export const CMP_WAIT_MAX_MS = 2000

/**
 * How often the CMP is asked during the wait.
 *
 * @type {number}
 */
export const CMP_WAIT_INTERVAL_MS = 50

/**
 * After a timed out wait, PMW keeps asking at a slower pace, so a CMP that
 * reports late without raising an event PMW listens to still lifts the
 * fail-safe denial.
 *
 * @type {number}
 */
export const CMP_LATE_POLL_INTERVAL_MS = 250

/**
 * How long the slower follow-up keeps asking.
 *
 * @type {number}
 */
export const CMP_LATE_POLL_MAX_MS = 30000

/**
 * A clock for the waited time in the logs. The bounds themselves are timers,
 * so they hold however the clock is read.
 *
 * @returns {number}
 */
const now = () => typeof performance !== "undefined" && typeof performance.now === "function"
	? performance.now()
	: Date.now()

/**
 * The CMPs whose loader script is on the page.
 *
 * @param {Array<Object>} cmps
 * @returns {Array<Object>}
 */
export const findAsyncCmps = (cmps) => cmps.filter((cmp) => {

	if (typeof cmp?.asyncLoader?.isPresent !== "function") return false

	try {
		return cmp.asyncLoader.isPresent() === true
	} catch (e) {
		return false
	}
})

/**
 * A readable name for the CMPs PMW waits for.
 *
 * @param {Array<Object>} cmps
 * @returns {string}
 */
export const namesOf = (cmps) => cmps.map((cmp) => cmp.name || "the CMP").join(" or ")

/**
 * Ask every candidate once, and return the first one that can answer.
 *
 * @param {Array<Object>} candidates
 * @param {Map<Object, Object>} contexts - one context object per candidate
 * @returns {{cmp: Object, result: Object}|null}
 */
export const pollCandidates = (candidates, contexts) => {

	for (const cmp of candidates) {

		if (!contexts.has(cmp)) contexts.set(cmp, {})

		let result

		try {
			result = cmp.asyncLoader.poll(contexts.get(cmp))
		} catch (e) {
			// A CMP whose API throws cannot answer yet. The cap still applies.
			result = null
		}

		if (isAnswer(result)) return {cmp, result}
	}

	return null
}

/**
 * Whether a poll result is one of the answers described at the top.
 *
 * @param {*} result
 * @returns {boolean}
 */
const isAnswer = (result) => {

	if (typeof result !== "object" || result === null) return false

	if (typeof result.decision === "object" && result.decision !== null) return true

	return "consent" in result && (result.consent === null || typeof result.consent === "object")
}

/**
 * Wait until a candidate answers, something else settles the consent state,
 * or the cap is reached.
 *
 * `settled` reports whether a decision or a CMP default came in through
 * another path in the meantime, most of all the CMP's own events, which the
 * adapters listen to from before the wait starts. `subscribe` lets such a
 * signal end the wait at once instead of at the next poll.
 *
 * @param {Object} options
 * @param {Array<Object>} options.candidates
 * @param {Map<Object, Object>} options.contexts
 * @param {function(): boolean} options.settled
 * @param {function(function(): void): (function(): void)} [options.subscribe]
 * @param {number} [options.maxWait]
 * @param {number} [options.interval]
 * @returns {Promise<{status: "ready"|"settled"|"timeout", elapsed: number, cmp?: Object, result?: Object}>}
 */
export const waitForAsyncCmp = ({
									candidates,
									contexts,
									settled,
									subscribe,
									maxWait = CMP_WAIT_MAX_MS,
									interval = CMP_WAIT_INTERVAL_MS,
								}) => new Promise((resolve) => {

	const started = now()

	let done        = false
	let pollTimer   = null
	let unsubscribe = null

	const finish = (status, extra = {}) => {

		if (done) return

		done = true
		clearTimeout(pollTimer)
		clearTimeout(deadlineTimer)
		if (typeof unsubscribe === "function") unsubscribe()

		resolve({status, elapsed: Math.round(now() - started), ...extra})
	}

	const check = () => {

		if (done) return

		if (settled()) return finish("settled")

		const answer = pollCandidates(candidates, contexts)

		if (answer) return finish("ready", answer)

		clearTimeout(pollTimer)
		pollTimer = setTimeout(check, interval)
	}

	// Timer based rather than clock based, so the bound holds however the
	// clock is read. One last look before giving up.
	const deadlineTimer = setTimeout(() => {

		if (done) return

		if (settled()) return finish("settled")

		const answer = pollCandidates(candidates, contexts)

		finish(answer ? "ready" : "timeout", answer || {})
	}, maxWait)

	if (typeof subscribe === "function") unsubscribe = subscribe(check)

	check()
})

/**
 * Keep asking after a timed out wait, until a candidate answers, something
 * else settles the consent state, or CMP_LATE_POLL_MAX_MS is over.
 *
 * @param {Object} options
 * @param {Array<Object>} options.candidates
 * @param {Map<Object, Object>} options.contexts
 * @param {function(): boolean} options.settled
 * @param {function({cmp: Object, result: Object}): void} options.onAnswer
 * @param {number} [options.maxWait]
 * @param {number} [options.interval]
 * @returns {function(): void} stops the follow-up
 */
export const pollLate = ({
							 candidates,
							 contexts,
							 settled,
							 onAnswer,
							 maxWait = CMP_LATE_POLL_MAX_MS,
							 interval = CMP_LATE_POLL_INTERVAL_MS,
						 }) => {

	let timer   = null
	let stopped = false

	const stop = () => {
		stopped = true
		clearTimeout(timer)
		clearTimeout(deadlineTimer)
	}

	const deadlineTimer = setTimeout(() => stop(), maxWait)

	const check = () => {

		if (stopped) return

		if (settled()) return stop()

		const answer = pollCandidates(candidates, contexts)

		if (answer) {
			stop()
			onAnswer(answer)
			return
		}

		timer = setTimeout(check, interval)
	}

	timer = setTimeout(check, interval)

	return stop
}
