/**
 * Cookiebot
 * https://wordpress.org/plugins/cookiebot/
 * https://support.cookiebot.com/hc/en-us/articles/360016047000-Cookiebot-and-Google-Consent-Mode
 */
import {applyDefault, loaderScriptPresent, optInDefault, optOutDefault} from "../cmp-defaults.mjs"

const SOURCE = "Cookiebot"

export const cookiebot = {

	/**
	 * Get the Cookiebot cookie.
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		// let consent = "{stamp:%27z5ZnyohzGbbYMhDdKsdXYMG3VT5a4l7mPBcyMeFe8vasPesmw/X1sQ==%27%2Cnecessary:true%2Cpreferences:true%2Cstatistics:false%2Cmarketing:true%2Cmethod:%27explicit%27%2Cver:1%2Cutc:1712435323862%2Cregion:%27ch%27}"
		let consent = pmw.getCookie("CookieConsent")

		if (!consent) return null

		/**
		 * Cookiebot writes "-1" for a visitor in a region where its configuration
		 * asks for no consent. Cookiebot itself treats that as everything allowed.
		 * It parses as valid JSON, so it has to be caught before the object path,
		 * which would otherwise find no category at all.
		 */
		if (consent.replace(/['"]/g, "").trim() === "-1") {

			pmw.console.log("Cookiebot CMP consent detected (consent not required in this region)")

			return {
				statistics : true,
				marketing  : true,
				preferences: true,
				necessary  : true,
			}
		}

		consent = consentToJson(consent)

		if (!consent) {
			pmw.console.log("Cookiebot cookie could not be parsed. Ignoring it.")
			return null
		}

		/**
		 * A cookie that names no category carries no visitor decision. Reading one
		 * as consent would unblock every pixel before the visitor has answered the
		 * banner. Sibling of the Cookie Script guard in cookie-script.mjs and the
		 * Complianz guard in complianz.mjs.
		 */
		if (!["necessary", "preferences", "statistics", "marketing"].some(category => category in consent)) {
			pmw.console.log("Cookiebot cookie detected, but it carries no consent categories. Ignoring it.")
			return null
		}

		pmw.console.log("Cookiebot CMP consent detected")

		/**
		 * A category the cookie does not name is denied. Cookiebot's own JS API
		 * documents the same defaults, and granting an unknown is what the deny by
		 * default policy forbids. Same change as the iubenda reader in 1.58.10.
		 */
		return {
			statistics : consent.statistics ?? false,
			marketing  : consent.marketing ?? false,
			preferences: consent.preferences ?? false,
			necessary  : consent.necessary ?? true,
		}
	},

	/**
	 * What Cookiebot applies before the visitor has answered.
	 *
	 * In a region where it asks for consent, Cookiebot writes no CookieConsent
	 * cookie until the visitor answers, so the cookie reader finds nothing and
	 * PMW used to grant everything in implicit consent mode. Cookiebot states
	 * the law it applies to this visitor in Cookiebot.regulations: GDPR and
	 * LGPD are opt-in, CCPA is opt-out.
	 *
	 * uc.js loads asynchronously by default, so this usually only answers once
	 * CookiebotOnLoad has fired. See loadEventListeners().
	 *
	 * @returns {{consent: Object, detail: string}|null}
	 * @since 1.69.3
	 */
	getDefault: () => {

		const cookiebot = window.Cookiebot

		if (!cookiebot || cookiebot.hasResponse === true) return null

		const regulations = cookiebot.regulations || {}

		if (regulations.gdprApplies === true || regulations.lgpdApplies === true) {
			return {consent: optInDefault(), detail: regulations.gdprApplies === true ? "GDPR applies" : "LGPD applies"}
		}

		if (regulations.ccpaApplies === true) {
			return {consent: optOutDefault(), detail: "CCPA applies"}
		}

		return null
	},

	/**
	 * For the asynchronous CMP wait in cmp-wait.mjs.
	 *
	 * uc.js is loaded with the async attribute by default, and window.Cookiebot
	 * only knows the visitor's regulations once it has run.
	 *
	 * @since 1.69.3
	 */
	asyncLoader: {

		isPresent: () => loaderScriptPresent([
			"script#Cookiebot",
			"script[data-cbid]",
			"script[src*=\"consent.cookiebot.com/uc.js\"]",
			"script[src*=\"consent.cookiebot.eu/uc.js\"]",
		]),

		poll: () => {

			const cb = window.Cookiebot

			if (!cb || typeof cb !== "object") return null

			if (cb.hasResponse === true) {
				return {
					decision: mapCookiebotConsent(window.CookieConsent?.consent ?? cb.consent ?? {}),
					detail  : "stored answer",
				}
			}

			const regulations = cb.regulations

			if (
				typeof regulations !== "object"
				|| regulations === null
				|| !["gdprApplies", "ccpaApplies", "lgpdApplies"].some(key => typeof regulations[key] === "boolean")
			) {
				return null
			}

			const cmpDefault = cookiebot.getDefault()

			if (cmpDefault) return cmpDefault

			// No regulation applies to this visitor. Cookiebot then asks for no
			// consent and lets everything run, the same as its "-1" cookie.
			return {consent: optOutDefault(), detail: "no regulation applies"}
		},
	},

	/**
	 * Cookiebot
	 * 	If visitor accepts cookies in Cookiebot unblock the scripts
	 *
	 * 	Cookiebot requires the events to be attached to the window object not the document object
	 *
	 * 	https://www.cookiebot.com/en/developer/
	 */
	loadEventListeners: () => {

		window.addEventListener("CookiebotOnAccept", relayCookiebotDecision, true)

		/**
		 * Only an accept used to be relayed. A visitor who clicked decline, or
		 * withdrew an earlier accept, kept whatever PMW had applied before on
		 * that page, which in implicit consent mode is a grant for everything.
		 * Cookiebot fires CookiebotOnDecline for the in-page decline and again on
		 * every later page load of a visitor who declined.
		 *
		 * @since 1.69.3
		 */
		window.addEventListener("CookiebotOnDecline", relayCookiebotDecision, true)

		/**
		 * uc.js loads asynchronously by default, so on a first page view it is
		 * often not there yet when PMW reads the consent. CookiebotOnLoad is the
		 * point where Cookiebot knows the visitor's state. A stored answer is
		 * relayed here, the same as the accept and decline events do, and
		 * without one Cookiebot's default for the visitor's region applies.
		 *
		 * @since 1.69.3
		 */
		window.addEventListener("CookiebotOnLoad", () => {

			if (window.Cookiebot?.hasResponse === true) {
				relayCookiebotDecision()
				return
			}

			// No answer yet: apply the law Cookiebot applies to this visitor.
			const cmpDefault = cookiebot.getDefault()

			if (cmpDefault) applyDefault(SOURCE, cmpDefault.consent, cmpDefault.detail)
		}, true)
	},
}

/**
 * Relay the decision Cookiebot holds right now.
 *
 * The listeners are attached to window, and Cookiebot exposes the same object
 * as window.Cookiebot and window.CookieConsent. It is read from there rather
 * than from the event, so all three events share one reading.
 *
 * @returns {void}
 */
const relayCookiebotDecision = () => {

	const consent = window.CookieConsent?.consent ?? window.Cookiebot?.consent ?? {}

	pmw.consent.api.updateSelectively({...mapCookiebotConsent(consent), source: "cmp"})
}

/**
 * Map Cookiebot's consent object onto PMW's categories.
 *
 * A category the object does not name is denied, the same as in the cookie
 * reader above.
 *
 * @param consent {Object}
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 */
const mapCookiebotConsent = (consent) => ({
	statistics : consent.statistics === true,
	marketing  : consent.marketing === true,
	preferences: consent.preferences === true,
	necessary  : consent.necessary !== false,
})

/**
 * Parse the CookieConsent cookie.
 *
 * Cookiebot writes it either as JSON or as a JavaScript object literal with
 * single quoted values, in both cases URI encoded.
 *
 * @param consent {string}
 * @returns {Object|null} - null when the cookie cannot be parsed
 */
const consentToJson = (consent) => {

	try {

		let parsed

		if (isValidJson(consent)) {
			parsed = JSON.parse(consent)
		} else {
			consent = decodeURI(consent)
			consent = consent.replace(/'/g, "\"") // Replace single quotes with double quotes as JSON requires double quotes
			consent = decodeURIComponent(consent)
			consent = consent.replace(/(\w+):/g, "\"$1\":") // Add double quotes to keys
			parsed  = JSON.parse(consent)
		}

		// A cookie holding a bare number or string parses fine but has no
		// categories to read, and the `in` check on it would throw.
		if (typeof parsed !== "object" || parsed === null) return null

		return parsed

	} catch (e) {
		return null
	}
}

const isValidJson = (str) => {
	try {
		JSON.parse(str)
	} catch (e) {
		return false
	}
	return true
}
