/**
 * WP Cookie Consent
 *
 * Source: https://wordpress.org/plugins/gdpr-cookie-consent/
 */

import {cmpHint, defaultForModel} from "../cmp-defaults.mjs"

export const wpCookieConsent = {

	/**
	 * Get the WP Cookie Consent cookie.
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		let consent = pmw.getCookie("wpl_user_preference")

		/**
		 * WP Cookie Consent writes wpl_user_preference on the first page view,
		 * before the visitor has answered, with every optional category set to
		 * "no". Read as a decision it set visitorHasChosen, which in explicit
		 * consent mode skips the region check. Only wpl_viewed_cookie=yes, set
		 * when the banner is answered, makes the preference a decision. Before
		 * that the banner's default applies (see getDefault()).
		 */
		if (consent && pmw.getCookie("wpl_viewed_cookie") !== "yes") {
			pmw.console.log("WP Cookie Consent preference cookie present, but the visitor hasn't answered the banner yet. Ignoring it.")
			return null
		}

		if (consent) {

			try {
				consent = JSON.parse(consent)
			} catch (e) {
				pmw.console.log("WP Cookie Consent cookie could not be parsed. Ignoring it.")
				return null
			}

			if (typeof consent !== "object" || consent === null) return null

			pmw.console.log("WP Cookie Consent CMP (by wpeka.com) consent detected")

			return {
				statistics : consent.analytics !== "no",
				marketing  : consent.marketing !== "no",
				preferences: consent.preferences !== "no",
				necessary  : consent.necessary !== "no",
			}
		}

		return null
	},

	/**
	 * What WP Cookie Consent applies before the visitor has answered, from the
	 * law its banner follows. Its settings are localized in the footer and its
	 * region rules are evaluated in the browser, so PMW takes the model from
	 * the server-side hint, which exists only when the banner follows the same
	 * law for every visitor.
	 *
	 * A decision is read from the wpl_user_preference cookie on the next page.
	 *
	 * @returns {{consent: Object, detail: string}|null}
	 * @since 1.69.3
	 */
	getDefault: () => {

		const hint = cmpHint("wp_cookie_consent")
		const consent = defaultForModel(hint?.model)

		return consent ? {consent, detail: `${hint.model}, from server hint`} : null
	},

	/**
	 * WP Cookie Consent Event Listeners
	 *
	 * Source: https://club.wpeka.com/docs/wp-cookie-consent/settings/integrating-your-actions/
	 * Support ticket: https://wordpress.org/support/topic/gdprcookieconsentonaccept-event-never-triggered/
	 */
	loadEventListeners: () => {

		// WP Cookie Consent emits a custom event called GdprCookieConsentOnAccept
		// The event doesn't work. Probably it is not bubbling up.
		// document.addEventListener("GdprCookieConsentOnAccept", function (e) {
		// 	console.log("GdprCookieConsentOnAccept", e.detail)
		// }, true)

		const buttonIds = [
			"cookie_action_accept",
			"cookie_action_reject",
		]

		buttonIds.forEach((buttonId) => {
			const buttonElement = document.getElementById(buttonId)

			if (buttonElement) {
				buttonElement.addEventListener("click", () => {
					/**
					 * Don't reload the page! (CMPs might emit the events on each page load, leading to a page reload loop)
					 * Only try to save the consent in the PMW.
					 */
				}, true)
			}
		})

	},
}
