/**
 * Iubenda
 * https://wordpress.org/plugins/iubenda-cookie-law-solution/
 * https://www.iubenda.com/en/help/1177-cookie-solution-how-to-detect-consent-and-preferences
 */
import {optInDefault} from "../cmp-defaults.mjs"

export const iubenda = {

	/**
	 * Get the Iubenda cookie.
	 * Then parse it and return the analytics and marketing values.
	 *
	 * 1 = Necessary
	 * 2 = Functionality
	 * 3 = Experience
	 * 4 = Measurement
	 * 5 = Marketing
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 * */
	getConsent: () => {

		let consent = getStoredConsent()

		if (!consent) {
			logMissingConsentCookie()
			return null
		}

		/**
		 * Iubenda writes cookies that carry no purposes at all, for example in its
		 * US privacy modes. Those state no category decision, and reading the
		 * purposes off them used to throw, which aborted the whole CMP reader loop
		 * and left every later CMP unread. Sibling of the Cookiebot guard in
		 * cookiebot.mjs.
		 */
		if (typeof consent.purposes !== "object" || consent.purposes === null) {
			pmw.console.log("Iubenda cookie detected, but it carries no consent purposes. Ignoring it.")
			return null
		}

		pmw.console.log("Iubenda CMP consent detected")

		return {
			statistics : consent.purposes["4"] ?? false,
			marketing  : consent.purposes["5"] ?? false,
			preferences: (consent.purposes["2"] || consent.purposes["3"]) ?? false,
			necessary  : consent.purposes["1"] ?? true,
		}
	},

	/**
	 * What Iubenda applies before the visitor has answered.
	 *
	 * The snippet configuration is inline in the head, so it is there when PMW
	 * reads the consent. With GDPR enabled and applied globally, which are
	 * Iubenda's defaults, every visitor gets an opt-in banner.
	 *
	 * With country detection, Iubenda decides per visitor, and only once its
	 * asynchronously loaded iubenda_cs.js has run. PMW applies no default then.
	 *
	 * @returns {{consent: Object, detail: string}|null}
	 * @since 1.69.3
	 */
	getDefault: () => {

		const configuration = window._iub?.csConfiguration

		if (typeof configuration !== "object" || configuration === null) return null

		if (configuration.countryDetection === true) return null

		if (configuration.enableGdpr !== false && configuration.gdprAppliesGlobally !== false) {
			return {consent: optInDefault(), detail: "GDPR applies to every visitor"}
		}

		return null
	},

	/**
	 * Iubenda CMP has no intelligent way of letting us know when the user has clicked the "Accept" button.
	 * We have to resort to a MutationObserver to listen for changes in the DOM.
	 * This is also why we have to reload the page when the user clicks the "Accept" button.
	 * Reading the cookies on the same page will not work because the cookies are not set in time when the observer is triggered.
	 */
	loadEventListeners: () => {

		// If the Iubenda CMP is not present, there's no need to continue
		if (!window._iub) return

		pmw.consent.cmpConsentClickObserver({
			ids    : ["iubFooterBtn"],
			classes: ["iubenda-cs-reject-btn", "iubenda-cs-accept-btn"],
		})
	},
}

/**
 * Matches the two names Iubenda gives its consent cookie, and neither the
 * -granular sibling nor any other _iub_cs-* cookie, because the name has to end
 * at the equal sign.
 *
 * _iub_cs-<cookiePolicyId>  : policy level storage, the older scheme
 * _iub_cs-s<siteId>         : site level storage, which the current snippet
 *                             turns on by default (storage.useSiteId), and
 *                             which Iubenda's own WordPress plugin matches
 *                             first in iubenda.class.php
 *
 * Requiring eight or more digits and no "s" made PMW miss the site level cookie
 * entirely. Consent then stayed at the denied defaults on those shops and every
 * marketing pixel stayed blocked, with no error anywhere.
 *
 * @type {RegExp}
 */
const consentCookieRegex = /^_iub_cs-s?\d+=/

/**
 * Iubenda's legacy cookie, from before it named the cookie after an ID at all.
 * Its `-granular` and `-uspr` siblings are excluded the same way as above.
 *
 * @type {RegExp}
 */
const legacyConsentCookieRegex = /^_iub_cs-local=/

/**
 * Read the decision Iubenda stored, from the current cookie if there is one and
 * from the legacy cookie otherwise.
 *
 * The cookie value is URI encoded JSON:
 * %7B%22timestamp%22%3A%222023-07-11T06%3A43%3A40.886Z%22%2C%22purposes%22%3A%7B%221%22%3Atrue%7D%2C%22id%22%3A63374232%7D
 *
 * Decoded, and with the name dropped, it looks like this:
 * {"timestamp":"2023-07-11T06:43:40.886Z","version":"1.48.0","purposes":{"1":true,"2":true,"4":true,"5":true},"id":63374232}
 *
 * @returns {Object|null}
 */
const getStoredConsent = () => {

	let cookie = pmw.getCookieThatContainsRegex(consentCookieRegex)

	if (cookie) {

		let consent = parseConsentCookie(cookie)

		if (!consent) {
			pmw.console.log("Iubenda cookie could not be parsed. Ignoring it.")
		}

		return consent
	}

	return getLegacyConsent()
}

/**
 * Iubenda still falls back to `_iub_cs-local` when the cookie named after the
 * storage ID is missing, and takes it only when the policy it was given for is
 * the policy the shop runs now. Its own reader, in iubenda_cs 1.105.0:
 *
 *   var e = getLocalCookie(consentNameLocal)
 *   if (!e) {
 *     var t = getLocalCookie(consentNameLocalOld)
 *     if ("" !== t && t.id === options.cookiePolicyId) e = t
 *   }
 *
 * Without this, a visitor whose consent predates the storage change, and whose
 * cookie was never migrated, is tracked under Iubenda's own rules while PMW
 * reads the shop as having no consent at all and blocks every pixel.
 *
 * @returns {Object|null}
 */
const getLegacyConsent = () => {

	let cookie = pmw.getCookieThatContainsRegex(legacyConsentCookieRegex)

	if (!cookie) return null

	let consent = parseConsentCookie(cookie)

	if (!consent) {
		pmw.console.log("Iubenda legacy cookie could not be parsed. Ignoring it.")
		return null
	}

	let cookiePolicyId = window._iub?.csConfiguration?.cookiePolicyId

	/**
	 * The ID is a number in the configuration and can be a string in the cookie,
	 * so the two are compared as strings. With no policy ID to compare against
	 * there is nothing tying the cookie to this shop, and Iubenda would not take
	 * it either, so neither does PMW.
	 */
	if (!cookiePolicyId || String(consent.id) !== String(cookiePolicyId)) {
		pmw.console.log("Iubenda legacy cookie found, but it was not given for this shop's cookie policy. Ignoring it.")
		return null
	}

	pmw.console.log("Iubenda legacy consent cookie detected")

	return consent
}

/**
 * Turn the raw "name=value" cookie into the object Iubenda stored in it.
 *
 * @param cookie {string}
 * @returns {Object|null} - null when the cookie cannot be parsed
 */
const parseConsentCookie = (cookie) => {

	// Cut at the first equal sign only. The value is JSON, and cutting at the
	// last one would eat the value whenever it contains an equal sign itself.
	let value = cookie.slice(cookie.indexOf("=") + 1)

	try {
		value = decodeURIComponent(value)
	} catch (e) {
		// A stray percent sign in a cookie that was written undecoded must not
		// throw here. Same guard as the OneTrust reader in onetrust.mjs: the
		// readers run one after another, so an error in one of them would leave
		// the whole consent state unresolved.
	}

	try {

		let parsed = JSON.parse(value)

		if (typeof parsed !== "object" || parsed === null) return null

		return parsed

	} catch (e) {
		return null
	}
}

/**
 * Name the Iubenda cookies the shop does have when none of them is the consent
 * cookie. Without this the shop owner only sees the generic "No CMP consent
 * detected", which is what let the site level cookie go unnoticed for so long.
 *
 * @returns {void}
 */
const logMissingConsentCookie = () => {

	if (!window._iub) return

	let names = document.cookie
		.split(";")
		.map(cookie => cookie.trim().split("=")[0])
		.filter(name => name.startsWith("_iub_cs"))

	if (names.length === 0) {
		pmw.console.log("Iubenda is present, but it has not written a consent cookie yet.")
		return
	}

	pmw.console.log(`Iubenda is present, but none of its cookies holds a consent decision PMW can read: ${names.join(", ")}`)
}
