/**
 * Borlabs Cookie
 * https://borlabs.io/borlabs-cookie/
 *
 * Borlabs Cookie 3 stores the decision in the borlabs-cookie cookie as JSON:
 *
 *   {"consents":{"essential":["borlabs-cookie"],"statistics":["google-analytics"]},
 *    "domainPath":"shop.example/","expires":"...","uid":"...","v3":true,"version":3}
 *
 * consents maps a service group to the services the visitor accepted. Borlabs
 * drops a group whose list is empty, and its own hasConsentForServiceGroup()
 * reads a group as accepted when the key is there. The cookie only counts
 * while its version matches the cookie version in the configuration; a newer
 * one means Borlabs asks again.
 *
 * Borlabs dispatches borlabs-cookie-consent-saved on document after it saved a
 * decision.
 *
 * Borlabs Cookie is opt-in by design. Its configuration, window.borlabsCookieConfig,
 * is only on the page while Borlabs Cookie is switched on for the request, and
 * it is what proves that its banner and its decision event will be there. The
 * pre-decision default is applied only then; with Borlabs switched off, or in
 * setup mode for a visitor who is not an admin, nothing changes.
 *
 * @since 1.69.3
 */

import {optInDefault} from "../cmp-defaults.mjs"

const COOKIE_NAME = "borlabs-cookie"

/**
 * PMW category -> Borlabs service groups. Borlabs 3 ships essential,
 * statistics, marketing and external media.
 */
const GROUPS = {
	statistics : ["statistics"],
	marketing  : ["marketing"],
	preferences: ["preferences", "functional"],
}

export const borlabsCookie = {

	/**
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		const consents = readDecision()

		if (!consents) return null

		pmw.console.log("Borlabs Cookie CMP consent detected")

		return mapConsents(consents)
	},

	/**
	 * @returns {{consent: Object, detail: string}|null}
	 */
	getDefault: () => {

		if (!isActiveOnPage()) return null
		if (readDecision()) return null

		return {consent: optInDefault(), detail: "opt-in, no decision yet"}
	},

	loadEventListeners: () => {

		document.addEventListener("borlabs-cookie-consent-saved", () => {

			const consents = readDecision() || readDecisionFromApi()

			if (!consents) {
				pmw.console.log("Borlabs Cookie saved a decision, but PMW could not read it.")
				return
			}

			pmw.consent.api.updateSelectively({...mapConsents(consents), source: "cmp"})
		}, true)
	},
}

/**
 * @returns {boolean}
 */
const isActiveOnPage = () => typeof window.borlabsCookieConfig === "object" && window.borlabsCookieConfig !== null

/**
 * The consents of a valid decision cookie.
 *
 * @returns {Object|null}
 */
const readDecision = () => {

	const raw = pmw.getCookie(COOKIE_NAME)

	if (!raw) return null

	let cookie

	try {
		cookie = JSON.parse(raw)
	} catch (e) {
		pmw.console.log("Borlabs Cookie cookie could not be parsed. Ignoring it.")
		return null
	}

	if (typeof cookie?.consents !== "object" || cookie.consents === null) return null

	const configuredVersion = window.borlabsCookieConfig?.settings?.cookieVersion

	if (configuredVersion !== undefined && Number(cookie.version) !== Number(configuredVersion)) {
		pmw.console.log("Borlabs Cookie cookie detected, but it was given for an earlier cookie version. Ignoring it.")
		return null
	}

	return cookie.consents
}

/**
 * Borlabs' own view of the cookie, for when reading the cookie directly fails.
 *
 * @returns {Object|null}
 */
const readDecisionFromApi = () => {

	try {
		const consents = window.BorlabsCookie?.Cookie?.getPluginCookie?.()?.consents

		return typeof consents === "object" && consents !== null ? consents : null
	} catch (e) {
		return null
	}
}

/**
 * @param consents {Object}
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 */
const mapConsents = (consents) => {

	const accepted = (groups) => groups.some(group => Array.isArray(consents[group]) && consents[group].length > 0)

	return {
		statistics : accepted(GROUPS.statistics),
		marketing  : accepted(GROUPS.marketing),
		preferences: accepted(GROUPS.preferences),
		necessary  : true,
	}
}
