/**
 * Helpers for the CMP integrations' pre-decision defaults.
 *
 * A CMP default is what a CMP applies before the visitor has answered its
 * banner. It is not a decision; consent.mjs applies it only in implicit consent
 * mode and only until a decision is in. See applyCmpDefault() there.
 *
 * @since 1.69.3
 */

/**
 * Nothing but the necessary category, which is what an opt-in banner applies
 * before it is answered.
 *
 * @param {Object} [granted] - categories the CMP grants anyway, for example
 *        statistics that a CMP runs without consent
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 */
export const optInDefault = (granted = {}) => ({
	statistics : granted.statistics === true,
	marketing  : granted.marketing === true,
	preferences: granted.preferences === true,
	necessary  : true,
})

/**
 * Everything, which is what an opt-out banner applies until the visitor objects.
 *
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 */
export const optOutDefault = () => ({
	statistics : true,
	marketing  : true,
	preferences: true,
	necessary  : true,
})

/**
 * Normalize the consent type names CMPs use ("optin", "optinstats", "opt-in",
 * "opt_out", ...) to "optin" or "optout".
 *
 * @param {*} type
 * @returns {"optin"|"optout"|null}
 */
export const normalizeModel = (type) => {

	if (typeof type !== "string" || type === "") return null

	const normalized = type.toLowerCase().replace(/[-_\s]/g, "")

	if (normalized.startsWith("optin")) return "optin"
	if (normalized === "optout") return "optout"

	return null
}

/**
 * The default a consent model stands for.
 *
 * @param {*} model
 * @returns {Object|null}
 */
export const defaultForModel = (model) => {

	const normalized = normalizeModel(model)

	if (normalized === "optin") return optInDefault()
	if (normalized === "optout") return optOutDefault()

	return null
}

/**
 * The server-printed consent model for a CMP. See
 * Environment::get_cmp_consent_hints() on the PHP side.
 *
 * @param {string} key
 * @returns {Object|null}
 */
export const cmpHint = (key) => pmw.consent?.getCmpHint?.(key) ?? null

/**
 * Hand a default that became known after load to consent.mjs.
 *
 * @param {string} source - the CMP's name, as in cmps.mjs
 * @param {Object|null} consent
 * @param {string} [detail]
 * @returns {boolean} whether it was applied
 */
export const applyDefault = (source, consent, detail = "") => {

	if (!consent) return false

	return pmw.consent?.applyCmpDefault?.({consent, source, detail}) === true
}

/**
 * Map a list of accepted category slugs onto PMW's categories.
 *
 * @param {string[]} accepted
 * @param {{statistics: string[], marketing: string[], preferences: string[]}} slugs
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 */
export const fromAcceptedSlugs = (accepted, slugs) => {

	const list = Array.isArray(accepted) ? accepted : []

	return {
		statistics : slugs.statistics.some(slug => list.includes(slug)),
		marketing  : slugs.marketing.some(slug => list.includes(slug)),
		preferences: slugs.preferences.some(slug => list.includes(slug)),
		necessary  : true,
	}
}

/**
 * Whether a CMP's loader script is in the DOM.
 *
 * The asynchronous CMP wait (cmp-wait.mjs) keys on the loader itself, never
 * on a plugin flag, so a shop that has the plugin but prints no loader costs
 * its visitors nothing.
 *
 * @param {string[]} selectors - CSS selectors, any one of which matches
 * @returns {boolean}
 * @since 1.69.3
 */
export const loaderScriptPresent = (selectors) => {

	try {
		return document.querySelector(selectors.join(",")) !== null
	} catch (e) {
		return false
	}
}
