/**
 * Real Cookie Banner (free and Pro)
 * https://wordpress.org/plugins/real-cookie-banner/
 *
 * Real Cookie Banner prints its frontend configuration into
 * window.realCookieBanner.others.frontend: the name of the decision cookie,
 * the current revision hash, and the service groups with their services.
 *
 * The decision cookie holds "<createdAt>:<uuids>:<revisionHash>:<decisionJson>",
 * where the decision maps a group id to the ids of the services the visitor
 * accepted. A decision only counts for the revision it was given for; after a
 * new revision Real Cookie Banner asks again. This is what its own
 * getUserDecision(true) checks.
 *
 * Consent in Real Cookie Banner is per service. PMW's categories map to the
 * groups: a category is granted when the visitor accepted every service of
 * the matching group, which is what accepting the group does. A visitor who
 * picked single services of a group is not read as having accepted the group,
 * because PMW cannot tell which of them stands for which pixel.
 *
 * After it applied a decision, Real Cookie Banner dispatches RCB/OptIn/All and
 * RCB/OptOut/All on document.
 *
 * Real Cookie Banner is opt-in by design. Its configuration is only on the
 * page while it runs for the request, and it is what proves that its banner and
 * its decision events will be there, so the pre-decision default is applied
 * only then.
 *
 * @since 1.69.3
 */

import {optInDefault} from "../cmp-defaults.mjs"

/**
 * Group slug or name stems per PMW category. The groups are terms created
 * with localized names, so their slugs depend on the language the shop was
 * set up in. A group that matches nothing is left out.
 */
const GROUP_PATTERNS = {
	statistics : /statist|analyt|estad|statys|mesure|messung/i,
	marketing  : /market|werbung|advert|publicit|pubblicit|reklam|mercad/i,
	preferences: /funct|funkt|fonction|funzion|funcion|prefer|praferen|komfort/i,
}

const DECISION_PATTERN = /^(\d+)?:?((?:[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12},?)+):([a-f0-9]{32}):(.*)$/

export const realCookieBanner = {

	/**
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		const frontend = getFrontend()

		if (!frontend) return null

		const decision = readDecision(frontend)

		if (!decision) return null

		pmw.console.log("Real Cookie Banner CMP consent detected")

		return mapDecision(decision, frontend.groups)
	},

	/**
	 * @returns {{consent: Object, detail: string}|null}
	 */
	getDefault: () => {

		const frontend = getFrontend()

		if (!frontend) return null
		if (readDecision(frontend)) return null

		return {consent: optInDefault(), detail: "opt-in, no decision yet"}
	},

	loadEventListeners: () => {

		const relay = () => {

			const frontend = getFrontend()
			const decision = frontend ? readDecision(frontend) : null

			// Real Cookie Banner also applies its essentials before any
			// decision. Without a decision cookie there is nothing to relay.
			if (!decision) return

			pmw.consent.api.updateSelectively({...mapDecision(decision, frontend.groups), source: "cmp"})
		}

		document.addEventListener("RCB/OptIn/All", relay, true)
		document.addEventListener("RCB/OptOut/All", relay, true)
	},
}

/**
 * @returns {{decisionCookieName: string, revisionHash: string, groups: Object[]}|null}
 */
const getFrontend = () => {

	const frontend = window.realCookieBanner?.others?.frontend

	if (
		typeof frontend?.decisionCookieName !== "string"
		|| typeof frontend?.revisionHash !== "string"
		|| !Array.isArray(frontend?.groups)
	) {
		return null
	}

	return frontend
}

/**
 * The accepted services per group id, for a decision of the current revision.
 *
 * Real Cookie Banner's own consent manager answers this when it is there, and
 * the decision cookie is parsed the same way otherwise.
 *
 * @param frontend {Object}
 * @returns {Object|null}
 */
const readDecision = (frontend) => {

	try {
		const manager = window.rcbConsentManager

		if (typeof manager?.getUserDecision === "function") {

			const decision = manager.getUserDecision(true)

			return decision && typeof decision.consent === "object" ? decision.consent : null
		}
	} catch (e) {
		// fall through to the cookie
	}

	const raw = pmw.getCookie(frontend.decisionCookieName)

	if (!raw) return null

	const match = raw.match(DECISION_PATTERN)

	if (!match) return null

	if (match[3] !== frontend.revisionHash) {
		pmw.console.log("Real Cookie Banner decision detected, but it was given for an earlier revision. Ignoring it.")
		return null
	}

	try {
		const consent = JSON.parse(match[4])

		return typeof consent === "object" && consent !== null ? consent : null
	} catch (e) {
		return null
	}
}

/**
 * @param decision {Object} - group id => accepted service ids
 * @param groups {Object[]}
 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}}
 */
const mapDecision = (decision, groups) => {

	const granted = (pattern) => {

		const matching = groups.filter(group =>
			!group.isEssential
			&& Array.isArray(group.items)
			&& group.items.length > 0
			&& (pattern.test(String(group.slug || "")) || pattern.test(String(group.name || ""))),
		)

		if (matching.length === 0) return false

		return matching.every(group => {

			const accepted = decision[group.id] ?? decision[String(group.id)]

			return Array.isArray(accepted) && group.items.every(item => accepted.includes(item.id))
		})
	}

	return {
		statistics : granted(GROUP_PATTERNS.statistics),
		marketing  : granted(GROUP_PATTERNS.marketing),
		preferences: granted(GROUP_PATTERNS.preferences),
		necessary  : true,
	}
}
