/**
 * Complianz Cookie
 * https://wordpress.org/plugins/complianz-gdpr/
 *
 * TODO: Inform the developers. The event listener fires four times and has inconsistent data. As a consequence PMW has to update the consent status also four times which is inefficient.
 */

import {applyDefault, cmpHint, normalizeModel, optInDefault, optOutDefault} from "../cmp-defaults.mjs"

const SOURCE = "Complianz"

/**
 * The consent type that applies to this visitor, as far as it is known yet.
 *
 * window.complianz is localized in the footer, so while PMW reads the consent
 * state it usually does not exist yet. With geo IP, its consenttype is also
 * only the site default until Complianz has fetched the visitor's own type,
 * which it then keeps in sessionStorage.cmplz_user_data for the session. The
 * server-printed hint exists only when the type is the same for everyone.
 *
 * "optinstats" is only ever in window.wp_consent_type; for PMW it is opt-in.
 *
 * @returns {{type: string, from: string}|null}
 */
const resolveConsentType = () => {

	const userData = readUserData()

	if (userData?.consenttype) return {type: userData.consenttype, from: "visitor region"}

	const complianz = window.complianz

	if (complianz?.consenttype && Number(complianz.geoip) !== 1) return {type: complianz.consenttype, from: "configuration"}

	const hint = cmpHint("complianz")

	if (hint?.model) return {type: hint.model, from: "server hint"}

	return null
}

/**
 * @returns {Object|null}
 */
const readUserData = () => {

	try {
		const raw = window.sessionStorage?.getItem("cmplz_user_data")

		if (!raw) return null

		const parsed = JSON.parse(raw)

		return typeof parsed === "object" && parsed !== null ? parsed : null
	} catch (e) {
		return null
	}
}

/**
 * Whether an unset category may be read as consent, following Complianz' own
 * cmplz_has_consent(): under the "optout" and "other" consent types it may,
 * under "optin" (the GDPR default) only an explicit "allow" counts.
 *
 * While the consent type is still unknown, which is the case when Complianz'
 * own script has not run yet, an unset category must not grant anything in
 * explicit consent mode.
 *
 * @returns {boolean}
 */
const impliedConsentApplies = () => {

	const resolved = resolveConsentType()

	if (resolved) return resolved.type === "optout" || resolved.type === "other"

	return !pmw.consent.explicitConsentModeActive()
}

/**
 * @param value {string} - the raw cookie value
 * @returns {boolean}
 */
const hasConsent = (value) => {

	if (value === "allow") return true
	if (value !== "") return false

	return impliedConsentApplies()
}

const readCategoryCookies = () => ({
	statistics : pmw.getCookie("cmplz_statistics") || pmw.getCookie("cmplz_rt_statistics"),
	marketing  : pmw.getCookie("cmplz_marketing") || pmw.getCookie("cmplz_rt_marketing"),
	preferences: pmw.getCookie("cmplz_preferences") || pmw.getCookie("cmplz_rt_preferences"),
	necessary  : pmw.getCookie("cmplz_functional") || pmw.getCookie("cmplz_rt_functional"),
})

const readBannerStatus = () => pmw.getCookie("cmplz_consent_status") || pmw.getCookie("cmplz_banner-status") || pmw.getCookie("cmplz_rt_banner-status")

/**
 * Whether the visitor has answered the banner. Complianz itself reads the
 * banner as answered on "dismissed" and on nothing else.
 *
 * @returns {boolean}
 */
const bannerAnswered = () => readBannerStatus() === "dismissed"

/**
 * The state Complianz writes on its own on an opt-in first page view when it
 * runs statistics without consent (forceEnableStats): cmplz_statistics=allow
 * and nothing else. Read as a decision, the unset marketing category went
 * through impliedConsentApplies(), which grants in implicit consent mode while
 * window.complianz is not there yet, so marketing pixels fired before the
 * banner was answered.
 *
 * @param values {Object}
 * @returns {boolean}
 * @since 1.69.3
 */
const isStatisticsOnlyPreDecision = (values) =>
	!bannerAnswered()
	&& values.statistics === "allow"
	&& values.marketing === ""
	&& values.preferences === ""

export const complianz = {

	/**
	 * Get the Complianz cookies
	 *
	 * @returns {{statistics: boolean, marketing: boolean, preferences: boolean, necessary: boolean}|null}
	 */
	getConsent: () => {

		const values = readCategoryCookies()

		const bannerStatus = readBannerStatus()

		/**
		 * Only a category cookie carries a visitor decision. Complianz also writes
		 * a banner status when it merely wants the banner shown again, for example
		 * for a new cookie policy revision or after a click on "manage consent",
		 * and it clears the category cookies while doing so. Without a category
		 * cookie PMW must not derive any consent, otherwise the mere presence of
		 * the banner cookie unblocks every pixel before the visitor has answered
		 * the banner. Sibling of the Cookie Script fix in 1.65.0.
		 */
		if (!Object.values(values).some(value => value !== "")) {

			if (bannerStatus) {
				pmw.console.log("Complianz cookie detected, but the visitor hasn't answered the banner yet. Ignoring it.")
			}

			return null
		}

		if (isStatisticsOnlyPreDecision(values)) {
			pmw.console.log("Complianz statistics cookie detected, but the visitor hasn't answered the banner yet. Reading it as Complianz' default.")
			return null
		}

		pmw.console.log("Complianz CMP consent detected")

		return {
			statistics : hasConsent(values.statistics),
			marketing  : hasConsent(values.marketing),
			preferences: hasConsent(values.preferences),
			// Functional is always allowed unless it has been denied explicitly.
			necessary  : values.necessary !== "deny",
		}
	},

	/**
	 * What Complianz applies before the visitor has answered: nothing but
	 * functional under opt-in, plus statistics when Complianz runs them without
	 * consent, and everything under opt-out and "other".
	 *
	 * @returns {{consent: Object, detail: string}|null}
	 * @since 1.69.3
	 */
	getDefault: () => {

		const resolved = resolveConsentType()

		if (!resolved) return null

		if (resolved.type === "other") {
			return {consent: optOutDefault(), detail: `consent type other, from ${resolved.from}`}
		}

		const model = normalizeModel(resolved.type)

		if (model === "optout") {
			return {consent: optOutDefault(), detail: `consent type ${resolved.type}, from ${resolved.from}`}
		}

		if (model === "optin") {

			const forcedStatistics = readCategoryCookies().statistics === "allow"
				|| Number(readUserData()?.forceEnableStats ?? window.complianz?.forceEnableStats) === 1

			return {
				consent: optInDefault({statistics: forcedStatistics}),
				detail : `consent type ${resolved.type}, from ${resolved.from}`,
			}
		}

		return null
	},

	/**
	 * Complianz Cookie
	 *
	 * If visitor accepts cookies in Complianz unblock the scripts
	 */
	loadEventListeners: () => {
		document.addEventListener("cmplz_fire_categories", cmplzStatusChange, true)
	},
}

/**
 * Complianz fires cmplz_fire_categories on every page load with the categories
 * it applies, before the visitor has answered as well as after, and again on
 * every decision. The pre-decision one is Complianz' own default for this
 * visitor, resolved for the visitor's region, which makes it the most precise
 * default there is. It used to be relayed as a decision.
 *
 * @param consent
 */
const cmplzStatusChange = (consent) => {

	const categories = consent?.detail?.categories

	if (!Array.isArray(categories)) return

	let data = {
		statistics : categories.includes("statistics"),
		marketing  : categories.includes("marketing"),
		preferences: categories.includes("preferences"),
		necessary  : categories.includes("functional"),
	}

	// Explicit consent mode keeps relaying every one of these as before: it
	// takes no CMP defaults, and without the relay a visitor under an opt-out
	// banner would stay blocked for as long as they do not click anything.
	if (!bannerAnswered() && !pmw.consent.explicitConsentModeActive()) {
		applyDefault(SOURCE, data, `pre-decision categories${consent.detail.region ? `, region ${consent.detail.region}` : ""}`)
		return
	}

	pmw.consent.api.updateSelectively({...data, source: "cmp"})
}
